-- ═══════════════════════════════════════════════════════════════════
-- supabase_dinamicas_seed.sql — As 247 dinámicas base
--
-- Ata agora vivían en src/datos.js: 160 kB que se descargan sempre, aínda
-- que non se abra a Guía, e que non se poden editar desde administración.
--
-- Executar no SQL Editor. Idempotente: as filas xa existentes non se tocan,
-- así que non se perden as edicións feitas desde Admin.
-- ═══════════════════════════════════════════════════════════════════

-- ⚠️ Decláranse TODAS as columnas, non só as que semellan novas.
-- A táboa `dinamicas` orixinal creouse hai tempo e non se sabe con certeza
-- que columnas ten: nunha instalación real faltaba `participantes`, e o
-- insert fallaba enteiro. `if not exists` fai que engadir unha que xa
-- estea sexa inofensivo, así que compensa listalas todas.
alter table public.dinamicas
  add column if not exists nombre        text,
  add column if not exists tipo          text,
  add column if not exists duracion      integer default 10,
  add column if not exists participantes text default 'grupo',
  add column if not exists descripcion   text,
  add column if not exists pasos         jsonb default '[]'::jsonb,
  add column if not exists objetivo      text,
  add column if not exists variantes     jsonb default '[]'::jsonb,
  add column if not exists notas         text,
  add column if not exists autoria       text,
  add column if not exists licencia      text,
  add column if not exists fuente        text,
  add column if not exists es_base       boolean default false,
  add column if not exists orde          integer default 0,
  add column if not exists user_id       uuid,
  add column if not exists created_at    timestamptz default now();

-- `pasos` e `variantes` teñen que ser jsonb. Se nalgunha instalación
-- quedaran como text, o insert fallaría por tipo incompatible.
do $$ begin
  alter table public.dinamicas alter column pasos type jsonb using
    case when pasos is null then '[]'::jsonb
         when jsonb_typeof(pasos::jsonb) is not null then pasos::jsonb
         else '[]'::jsonb end;
exception when others then null; end $$;

do $$ begin
  alter table public.dinamicas alter column variantes type jsonb using
    case when variantes is null then '[]'::jsonb
         when jsonb_typeof(variantes::jsonb) is not null then variantes::jsonb
         else '[]'::jsonb end;
exception when others then null; end $$;

create index if not exists dinamicas_tipo_idx on public.dinamicas(tipo);
create index if not exists dinamicas_base_idx on public.dinamicas(es_base);

insert into public.dinamicas
  (id, nombre, tipo, duracion, participantes, descripcion, pasos, objetivo,
   variantes, notas, autoria, licencia, fuente, es_base, orde, user_id)
values
  ('1', 'Sí, y...', 'calentamiento', 10, 'parejas', 'La regla de oro del impro. Aceptar y añadir información sin bloquear.', '["Ponerse en parejas","A dice algo / B responde ''Sí, y...''","Alternar 2 minutos","Reflexionar qué se construyó"]'::jsonb, 'Aceptación, escucha, construcción conjunta', '["Sí, pero...","Solo con preguntas"]'::jsonb, null, null, null, null, true, 0, null),
  ('2', 'Zip Zap Zop', 'calentamiento', 5, 'grupo', 'Círculo de energía con contacto visual y gesto preciso.', '["Círculo de pie","ZIP: al lado, ZAP: cruzar, ZOP: cualquier dirección","Mantener ritmo y contacto visual"]'::jsonb, 'Concentración, presencia, energía grupal', '["Con nombres","Silencioso"]'::jsonb, null, null, null, null, true, 1, null),
  ('3', 'Espejo emocional', 'calentamiento', 8, 'parejas', 'Liderazgo físico compartido sin palabras.', '["Parejas frente a frente","A empieza a moverse con una emoción","B sigue como espejo","El liderazgo puede cambiar"]'::jsonb, 'Escucha física, empatía, presencia', '["Grupo entero como espejo"]'::jsonb, null, null, null, null, true, 2, null),
  ('4', 'Entrevista al personaje', 'entrenamiento', 15, 'grupo', 'Sostener un personaje bajo presión de preguntas.', '["Sortear al entrevistado","Generar personaje con estímulos","5 minutos de entrevista libre","Responder siempre desde el personaje"]'::jsonb, 'Construcción de personaje, coherencia', '["Con cambio mid-entrevista"]'::jsonb, null, null, null, null, true, 3, null),
  ('5', 'Cortar y justificar', 'entrenamiento', 20, 'grupo', 'Sustituir a un actor congelado y justificar su posición.', '["Escena en curso","Facilitador grita ''¡Congela!''","Alguien ocupa la posición exacta","Justifica y propone nueva escena"]'::jsonb, 'Transformación, escucha corporal', '["Solo con poses ridículas"]'::jsonb, null, null, null, null, true, 4, null),
  ('6', 'Película en géneros', 'juego', 20, 'grupo', 'Una escena que cambia de género cinematográfico.', '["Fijar escena neutra","Director cambia el género gritándolo","El grupo adapta todo"]'::jsonb, 'Versatilidad, estilo, juego grupal', '["El público propone géneros"]'::jsonb, null, null, null, null, true, 5, null),
  ('7', 'Harold', 'formato', 45, 'grupo', 'El formato largo. Monólogos → escenas → conexiones.', '["Sugerencia del público","3 monólogos (45s c/u)","Rondas de escenas en tríos","Reincorporaciones y cierre"]'::jsonb, 'Narrativa larga, temática, conexiones', '["Harold de 30 min"]'::jsonb, null, 'Del Close — desenvolvido con Charna Halpern en iO (ImprovOlympic), Chicago. Orixe en The Committee, San Francisco', null, null, true, 6, null),
  ('8', 'Ópera improvisada', 'musical', 20, 'grupo', 'Toda la escena se canta. Sin hablar.', '["Sugerencia del público","Todo se canta","Estilo operístico: dramático, exagerado"]'::jsonb, 'Desinhibición vocal, drama, humor', '["Mezcla de estilos"]'::jsonb, null, null, null, null, true, 7, null),
  ('9', 'Ronda de una palabra', 'cierre', 5, 'grupo', 'Cada persona dice una sola palabra que resuma la sesión.', '["Círculo","Solo una palabra, sin explicación","El facilitador cierra"]'::jsonb, 'Integración, reflexión, cierre colectivo', '["Con gesto en lugar de palabra"]'::jsonb, null, null, null, null, true, 8, null),
  ('10', 'La máquina', 'juego', 10, 'grupo', 'El grupo construye una máquina humana con movimientos y sonidos repetitivos.', '["Una persona empieza","Cada uno se engancha","Facilitador pide acelerar o parar"]'::jsonb, 'Ritmo, cuerpo, coordinación', '["La máquina de emociones"]'::jsonb, null, null, null, null, true, 9, null),
  ('11', 'Asociación libre', 'calentamiento', 8, 'grupo', 'Círculo de palabras asociadas sin pensar. La velocidad es clave.', '["Círculo de pie","Una persona dice una palabra","La siguiente dice la primera que le venga","Sin pausas, sin censura"]'::jsonb, 'Desbloqueo mental, conexión grupal', '["Solo con categorías (animales, colores...)","En parejas"]'::jsonb, null, null, null, null, true, 10, null),
  ('12', 'Tableau vivant', 'calentamiento', 10, 'grupo', 'Crear imágenes congeladas con el cuerpo. Sin palabras.', '["Facilitador dice un concepto o situación","Grupo tiene 5 segundos para crear la imagen","Congelar y mantener","Observar y comentar"]'::jsonb, 'Expresión corporal, composición grupal', '["Con luz y sombra","El público adivina"]'::jsonb, null, null, null, null, true, 11, null),
  ('13', 'Máquina de sonidos', 'calentamiento', 12, 'grupo', 'Construir una máquina humana con sonido y movimiento repetitivo.', '["Una persona empieza con un movimiento y sonido repetitivo","Cada persona se engancha con su propio movimiento","Hasta formar una máquina completa","El facilitador puede pedir acelerar/frenar"]'::jsonb, 'Sincronización, escucha física', '["Máquina con tema (lavadora, cohete...)"]'::jsonb, null, null, null, null, true, 12, null),
  ('14', 'Experto absurdo', 'entrenamiento', 15, 'grupo', 'Hablar con total autoridad sobre un tema inventado.', '["Sortear tema absurdo","5 minutos de conferencia/entrevista","El grupo hace preguntas serias","El experto responde con lógica interna"]'::jsonb, 'Compromiso, coherencia interna, humor', '["Panel de expertos","Con PowerPoint imaginario"]'::jsonb, null, null, null, null, true, 13, null),
  ('15', 'Historia en ronda', 'entrenamiento', 15, 'grupo', 'Contar una historia colectiva. Cada persona añade una frase.', '["Sentados en círculo","La primera persona empieza la historia","Cada una añade exactamente una frase","Sin veto, aceptar todo"]'::jsonb, 'Narrativa colectiva, aceptación', '["Una palabra por persona","Con géneros forzados"]'::jsonb, null, null, null, null, true, 14, null),
  ('16', 'Cambio de emoción', 'entrenamiento', 18, 'parejas', 'Sostener una escena cambiando de emoción sin cambiar el texto.', '["Pareja elige una escena cotidiana con texto fijo","Facilitador dice emoción","Actúan la escena con esa emoción","Cambio cada 30 segundos"]'::jsonb, 'Versatilidad emocional, disociación texto/emoción', '["Solo con el cuerpo, sin texto"]'::jsonb, null, null, null, null, true, 15, null),
  ('17', 'Propuesta y aceptación', 'entrenamiento', 20, 'parejas', 'Una persona propone realidades, la otra las acepta sin excepción.', '["A propone una realidad (''Tu eres mi madre''...)","B acepta completamente y añade","Alternar roles cada 3 minutos","Reflexionar sobre el bloqueo habitual"]'::jsonb, 'Aceptación radical, construcción', '["Con 3 personas en rueda"]'::jsonb, null, null, null, null, true, 16, null),
  ('18', 'Emoción prestada', 'entrenamiento', 15, 'grupo', 'Entrar a una escena con la emoción del actor que se sale.', '["Escena en curso con 2 actores","Uno sale, el nuevo entra con su misma emoción exacta","La historia puede cambiar pero la emoción no","Rotación continua"]'::jsonb, 'Escucha emocional, coherencia', '["Con estados físicos en lugar de emociones"]'::jsonb, null, null, null, null, true, 17, null),
  ('19', 'Subtexto', 'entrenamiento', 20, 'parejas', 'La escena tiene un subtexto oculto que el público conoce pero los personajes no.', '["Facilitador susurra al público el subtexto real","Los actores juegan la escena normal","El humor surge de la brecha","Desvelar al final"]'::jsonb, 'Subtexto, doble sentido, presencia', '["El subtexto lo decide el público"]'::jsonb, null, null, null, null, true, 18, null),
  ('20', 'Formato: Armando', 'formato', 40, 'grupo', 'Escenas cortas conectadas por un personaje recurrente (Armando).', '["Establecer quién es Armando","Escenas de 3-4 min donde Armando aparece","Cada escena en un contexto diferente","Cierre con todas las líneas unidas"]'::jsonb, 'Personaje recurrente, coherencia narrativa', '["Con 2 personajes recurrentes"]'::jsonb, null, 'iO Chicago — nomeado por Armando Diaz', null, null, true, 19, null),
  ('21', 'Formato: Montaje', 'formato', 35, 'grupo', 'Escenas temáticas sin continuidad narrativa. Poético y coral.', '["Sugerencia abstracta del público","Escenas cortas de 1-3 min","Sin continuidad obligatoria","Ritmo y contraste entre escenas"]'::jsonb, 'Poesía escénica, variedad tonal', '["Con narrador en off"]'::jsonb, null, null, null, null, true, 20, null),
  ('22', 'Musical: Canción del personaje', 'musical', 15, 'grupo', 'Cada personaje en escena tiene derecho a una canción que exprese su estado interior.', '["Escena normal en curso","Cuando el personaje lo necesita, canta","El grupo hace de coro/acompañamiento","La escena continúa después"]'::jsonb, 'Exteriorización emocional, comicidad', '["Solo en momentos de crisis"]'::jsonb, null, null, null, null, true, 21, null),
  ('23', 'Musical: Rap battle', 'musical', 12, 'parejas', 'Dos personajes resuelven un conflicto a través del rap.', '["Establecer el conflicto entre dos personajes","Rap de 30 segundos cada uno, alternando","El público decide quién gana","Opcional: reconciliación cantada"]'::jsonb, 'Ritmo, argumento, presión creativa', '["Todo el grupo rapeando"]'::jsonb, null, null, null, null, true, 22, null),
  ('24', 'Musical: Género musical', 'musical', 18, 'grupo', 'Una escena normal se convierte en un género musical específico.', '["El público propone escena y género musical","Actuar la escena con canciones del género","El facilitador puede cambiar el género","Mantener coherencia narrativa"]'::jsonb, 'Versatilidad musical, humor', '["Mezcla de géneros simultáneos"]'::jsonb, null, null, null, null, true, 23, null),
  ('25', 'Cierre: Tres palabras', 'cierre', 6, 'grupo', 'Cada persona elige tres palabras que resuman la sesión o el show.', '["Círculo de pie","Cada persona dice sus tres palabras sin explicación","El facilitador puede hilar un poema final","Aplauso colectivo de cierre"]'::jsonb, 'Integración, reflexión, cierre colectivo', '["Solo una imagen corporal"]'::jsonb, null, null, null, null, true, 24, null),
  ('26', 'Cierre: Agradecimiento', 'cierre', 8, 'grupo', 'Ronda de agradecimientos específicos entre compañeros.', '["Círculo","Cada persona agradece algo concreto a alguien","Sin obligación de respuesta","El facilitador cierra con agradecimiento general"]'::jsonb, 'Vínculo grupal, reconocimiento', '["Escrito en papel y leído en voz alta"]'::jsonb, null, null, null, null, true, 25, null),
  ('27', 'Punto de vista', 'entrenamiento', 20, 'grupo', 'La misma escena desde el punto de vista de personajes distintos.', '["Escena base acordada","Representarla desde el PDV del protagonista","Repetir desde el antagonista","Repetir desde un testigo secundario"]'::jsonb, 'Empatía, narrativa múltiple', '["Con objetos o animales como narradores"]'::jsonb, null, null, null, null, true, 26, null),
  ('28', 'Movimiento y texto', 'entrenamiento', 15, 'parejas', 'El movimiento dicta el texto, no al revés.', '["A empieza a moverse por el espacio","El movimiento sugiere quién es y qué quiere","Hablar solo cuando el cuerpo lo pida","B reacciona de la misma manera"]'::jsonb, 'Fisicalidad, organicidad', '["Con música sin letra"]'::jsonb, null, null, null, null, true, 27, null),
  ('29', 'Escenas paralelas', 'formato', 25, 'grupo', 'Dos escenas simultáneas que se van interfiriendo.', '["Dos grupos inician escenas independientes","El facilitador corta y alterna","Las escenas se mezclan gradualmente","Un cierre unificado"]'::jsonb, 'Edición, ritmo, conexiones temáticas', '["Tres escenas paralelas"]'::jsonb, null, null, null, null, true, 28, null),
  ('30', 'Personaje animal', 'calentamiento', 10, 'grupo', 'Habitar un animal con todo el cuerpo antes de construir un personaje humano.', '["Moverse por el espacio como un animal","Ir incorporando rasgos humanos manteniendo el animal","Encontrarse con otros animales-personajes","Presentaciones cruzadas"]'::jsonb, 'Fisicalidad, desinhibición, personaje', '["Con música que sugiere el ritmo del animal"]'::jsonb, null, null, null, null, true, 29, null),
  ('31', 'Escucha activa', 'calentamiento', 8, 'parejas', 'Parar. Escuchar de verdad. Sin preparar la respuesta.', '["Parejas frente a frente","A habla 2 minutos de cualquier cosa real","B escucha sin preparar respuesta","B resume lo que escuchó","Cambiar"]'::jsonb, 'Presencia, escucha real', '["Solo con contacto visual, sin hablar"]'::jsonb, null, null, null, null, true, 30, null),
  ('32', 'Justificación física', 'entrenamiento', 15, 'grupo', 'Cada posición accidental del cuerpo debe justificarse narrativamente.', '["Dos en escena","Cuando el facilitador grita ¡Congela!","La siguiente persona ocupa una posición aleatoria","Justifica inmediatamente por qué está así"]'::jsonb, 'Justificación, reactividad, humor', '["Solo con poses de revista"]'::jsonb, null, null, null, null, true, 31, null),
  ('33', 'El regalo', 'entrenamiento', 12, 'parejas', 'Dar y recibir regalos imaginarios con total convicción.', '["A entrega un regalo imaginario (sin decir qué es)","B lo recibe y reacciona genuinamente","B describe lo que recibió","Alternar y aumentar la emotividad"]'::jsonb, 'Especificidad física, emocionalidad', '["Regalos terribles, regalos perfectos"]'::jsonb, null, null, null, null, true, 32, null),
  ('34', 'Status', 'entrenamiento', 20, 'grupo', 'Jugar con el status alto y bajo en escena. Quién tiene el poder cambia.', '["Asignar status del 1 al 10 a cada actor (secreto)","Escena libre donde cada uno juega su status","El público adivina el orden","Reflexionar sobre cómo se manifiesta"]'::jsonb, 'Presencia escénica, jerarquía, poder', '["Status que cambia durante la escena"]'::jsonb, null, null, null, null, true, 33, null),
  ('35', 'Narrador y actores', 'formato', 20, 'grupo', 'Un narrador omnisciente cuenta, los actores representan.', '["Elegir narrador","El narrador cuenta una historia en tiempo real","Los actores representan lo que se narra","El narrador puede modificar la realidad de los actores"]'::jsonb, 'Escucha, reactividad, narrativa', '["Narradores múltiples que se contradicen"]'::jsonb, null, null, null, null, true, 34, null),
  ('36', 'Pase de aplauso', 'calentamiento', 5, 'grupo', 'Un aplauso viaja por el círculo con contacto visual, cada vez más rápido.', '["Círculo de pie","Una persona ''lanza'' un aplauso a otra con la mirada","Esa persona lo recibe y lo pasa a otra","Acelerar progresivamente"]'::jsonb, 'Energía grupal, contacto visual, ritmo', '["Con sonido en vez de aplauso","Dos aplausos simultáneos"]'::jsonb, null, null, null, null, true, 35, null),
  ('37', 'Nombre y gesto', 'calentamiento', 8, 'grupo', 'Presentación con nombre acompañado de un gesto característico que el grupo repite.', '["Círculo de pie","Cada persona dice su nombre con un gesto","El grupo entero repite nombre y gesto","Segunda ronda: recordar el de la persona anterior"]'::jsonb, 'Memoria de grupo, desinhibición', '["Con sonido en vez de gesto"]'::jsonb, null, null, null, null, true, 36, null),
  ('38', 'Caminar y parar', 'calentamiento', 8, 'grupo', 'Ocupar el espacio de forma neutra, parando y arrancando a una señal.', '["Caminar por el espacio sin rutas fijas","A la señal ''stop'', congelarse","A la señal ''sigue'', retomar sin patrón","Añadir saludos con la mirada al cruzarse"]'::jsonb, 'Conciencia espacial, presencia neutra', '["Con distintas velocidades numeradas del 1 al 5"]'::jsonb, null, null, null, null, true, 37, null),
  ('39', 'Bola de energía', 'calentamiento', 6, 'grupo', 'Pasar una bola imaginaria que cambia de peso, tamaño y textura.', '["Círculo","Una persona ''lanza'' una bola imaginaria con una cualidad física","El receptor la transforma y la pasa a otra persona","Mantener la lógica física de cada transformación"]'::jsonb, 'Mimo, especificidad, imaginación compartida', '["La bola se convierte en un objeto concreto"]'::jsonb, null, null, null, null, true, 38, null),
  ('40', 'Suma uno', 'calentamiento', 6, 'grupo', 'Contar en grupo hasta un número sin ponerse de acuerdo en quién habla.', '["Círculo, sin orden establecido","Contar del 1 en adelante, una persona un número cada vez","Si dos hablan a la vez, se reinicia","Objetivo: llegar lo más alto posible"]'::jsonb, 'Escucha colectiva, atención al grupo', '["Con los ojos cerrados"]'::jsonb, null, null, null, null, true, 39, null),
  ('41', 'Espejo en parejas', 'calentamiento', 10, 'parejas', 'Uno lidera el movimiento, el otro lo refleja como un espejo.', '["Parejas frente a frente","A hace movimientos lentos, B los refleja","Cambiar el liderazgo sin avisar","Objetivo: que no se note quién lidera"]'::jsonb, 'Sincronía, atención, conexión física', '["Espejo de grupo con un líder oculto"]'::jsonb, null, null, null, null, true, 40, null),
  ('42', 'Onda sonora', 'calentamiento', 5, 'grupo', 'Un sonido y movimiento viajan por el círculo como una ola.', '["Círculo de pie","Una persona inicia un sonido+movimiento","La persona de al lado lo repite y pasa el turno","Dar la vuelta completa al círculo"]'::jsonb, 'Ritmo grupal, expresión física-vocal', '["La ola cambia de dirección a media vuelta"]'::jsonb, null, null, null, null, true, 41, null),
  ('43', 'Palmas rítmicas', 'calentamiento', 6, 'grupo', 'Crear y mantener un patrón rítmico colectivo con palmas y pies.', '["Círculo","Una persona propone un patrón simple","El grupo lo repite hasta estabilizarlo","Otra persona propone una capa nueva encima"]'::jsonb, 'Escucha musical, cohesión de grupo', '["Dividir el grupo en dos patrones simultáneos"]'::jsonb, null, null, null, null, true, 42, null),
  ('44', 'Presentación cruzada', 'calentamiento', 10, 'parejas', 'Entrevistarse en pareja y presentar al compañero al grupo.', '["Parejas se entrevistan 2 minutos cada una","Datos reales o inventados, según se acuerde","Cada persona presenta a su pareja al grupo","El grupo puede hacer una pregunta más"]'::jsonb, 'Escucha, síntesis, cohesión de grupo', '["Presentación en tercera persona exagerada"]'::jsonb, null, null, null, null, true, 43, null),
  ('45', 'El director de orquesta', 'calentamiento', 10, 'grupo', 'Un voluntario adivina quién dirige los movimientos que el grupo imita en círculo.', '["Una persona sale de la sala","El grupo elige un ''director'' en secreto","El director cambia de movimiento y el grupo lo sigue con disimulo","El voluntario vuelve e intenta adivinar quién dirige"]'::jsonb, 'Observación, sutileza, sincronía grupal', '["Con sonidos en vez de movimientos"]'::jsonb, null, null, null, null, true, 44, null),
  ('46', 'Bloqueo consciente', 'entrenamiento', 15, 'parejas', 'Practicar el bloqueo para reconocerlo, después repetir aceptando.', '["Escena corta donde A propone y B bloquea sistemáticamente","Parar y notar cómo se siente la escena","Repetir la misma escena aceptando todo","Comparar la diferencia de energía"]'::jsonb, 'Reconocer el bloqueo, valorar la aceptación', '["Bloqueo parcial: aceptar pero no añadir"]'::jsonb, null, null, null, null, true, 45, null),
  ('47', 'Especificidad', 'entrenamiento', 15, 'parejas', 'Prohibido lo genérico: cada objeto, lugar y nombre debe ser concreto.', '["Escena libre entre dos personas","El facilitador corta si algo es vago (''la cosa'', ''el sitio'')","Deben nombrar con precisión (marca, calle, nombre propio)","Reflexionar sobre cómo la precisión ayuda a la historia"]'::jsonb, 'Detalle, credibilidad, riqueza narrativa', '["Un narrador exige la especificidad en voz alta"]'::jsonb, null, null, null, null, true, 46, null),
  ('48', 'Reincorporación simple', 'entrenamiento', 18, 'grupo', 'Traer de vuelta un elemento de una escena anterior en una nueva.', '["Primera escena corta, con un detalle memorable","Segunda escena distinta y libre","Un actor debe reincorporar el detalle de la primera","El grupo identifica la conexión al final"]'::jsonb, 'Memoria de escena, callback, estructura', '["Reincorporar un objeto en vez de una frase"]'::jsonb, null, null, null, null, true, 47, null),
  ('49', 'Ralentí y aceleración', 'entrenamiento', 12, 'parejas', 'La misma escena jugada a distintas velocidades controladas.', '["Escena corta con acción física clara","Repetir a cámara lenta manteniendo la emoción","Repetir al doble de velocidad","Comparar qué información se pierde o se gana"]'::jsonb, 'Control del ritmo, claridad física', '["Cambios de velocidad dentro de la misma escena"]'::jsonb, null, null, null, null, true, 48, null),
  ('50', 'Relación antes que trama', 'entrenamiento', 18, 'parejas', 'Establecer la relación entre personajes antes de que pase nada.', '["Empezar la escena solo con miradas y postura","No hablar hasta que quede clara la relación","Recién entonces iniciar el diálogo","El grupo comenta qué relación percibió"]'::jsonb, 'Relación como base de la escena', '["Sin usar nunca la palabra que define la relación"]'::jsonb, null, null, null, null, true, 49, null),
  ('51', 'El as en la manga', 'entrenamiento', 15, 'parejas', 'Cada actor entra con una información secreta que debe revelar en el momento justo.', '["Cada actor recibe un dato secreto por escrito","Empiezan la escena sin compartirlo","Deben encontrar el momento orgánico para revelarlo","Analizar el timing elegido"]'::jsonb, 'Timing, escucha, construcción de tensión', '["El secreto lo conoce el público, no el otro actor"]'::jsonb, null, null, null, null, true, 50, null),
  ('52', 'Contradicción física', 'entrenamiento', 15, 'parejas', 'El cuerpo dice una cosa, las palabras dicen otra.', '["Escena con texto neutro acordado","Uno de los actores recibe una instrucción física secreta que contradice el texto","Jugar la escena manteniendo ambas capas","El grupo interpreta qué pasaba realmente"]'::jsonb, 'Subtexto físico, capas de significado', '["Los dos actores tienen contradicciones cruzadas"]'::jsonb, null, null, null, null, true, 51, null),
  ('53', 'Final antes que principio', 'entrenamiento', 15, 'grupo', 'Se decide el final de la escena antes de empezarla.', '["El grupo o el público define una imagen final","Los actores improvisan libremente sabiendo el final","Deben llegar a esa imagen de forma orgánica","Comentar cómo condicionó las decisiones"]'::jsonb, 'Construcción hacia un objetivo, planificación en el momento', '["El final es una frase exacta que debe decirse"]'::jsonb, null, null, null, null, true, 52, null),
  ('54', 'Objetos transformables', 'entrenamiento', 12, 'grupo', 'Un objeto imaginario cambia de identidad en cada uso.', '["Círculo con un objeto neutro imaginado (un palo, por ejemplo)","Cada persona lo usa como algo distinto y lo pasa","Debe quedar clara la nueva identidad sin explicarla","Dar dos vueltas completas al círculo"]'::jsonb, 'Mimo, transformación, claridad física', '["El objeto conserva memoria de usos anteriores"]'::jsonb, null, null, null, null, true, 53, null),
  ('55', 'Discurso emocional', 'entrenamiento', 15, 'grupo', 'Dar un discurso mantiene el contenido pero cambia de emoción a una señal.', '["Una persona empieza un discurso sobre cualquier tema","El facilitador grita una emoción nueva","El orador continúa el mismo discurso con esa emoción","Repetir con 4-5 emociones distintas"]'::jsonb, 'Versatilidad emocional, coherencia de contenido', '["El discurso cambia también de género (político, poético...)"]'::jsonb, null, null, null, null, true, 54, null),
  ('56', 'Escena a tres tiempos', 'entrenamiento', 20, 'grupo', 'Una misma escena se juega en pasado, presente y futuro imaginado.', '["Escena corta que plantea un conflicto","Repetir mostrando el pasado que llevó hasta ahí","Repetir mostrando un futuro posible","Comentar qué añadió cada capa temporal"]'::jsonb, 'Estructura temporal, contexto narrativo', '["El público elige qué tiempo ver primero"]'::jsonb, null, null, null, null, true, 55, null),
  ('57', 'Regla oculta', 'entrenamiento', 15, 'grupo', 'Una escena tiene una regla secreta que el público debe descubrir jugando.', '["El facilitador da una regla física o verbal secreta a los actores","Actúan la escena respetando la regla sin nombrarla","El público intenta adivinar la regla al final","Repetir con una regla distinta"]'::jsonb, 'Consistencia, juego de patrones', '["La regla la propone el propio público"]'::jsonb, null, null, null, null, true, 56, null),
  ('58', 'Voz interior', 'entrenamiento', 15, 'parejas', 'Un actor dice lo que su personaje piensa realmente, en paralelo a lo que dice.', '["Escena normal entre dos personajes","A una señal, el actor congela y dice su pensamiento interno en voz alta","La escena continúa como si no se hubiera dicho","Alternar entre los dos actores"]'::jsonb, 'Subtexto explícito, comedia, profundidad', '["El pensamiento interno lo dice el compañero"]'::jsonb, null, null, null, null, true, 57, null),
  ('59', 'Escalada de conflicto', 'entrenamiento', 15, 'parejas', 'Un desacuerdo mínimo debe crecer de forma lógica y progresiva.', '["Empezar con un desacuerdo trivial (quién friega los platos)","Cada intervención debe subir un poco la intensidad","No saltar directamente a los extremos","Encontrar el pico y luego resolver"]'::jsonb, 'Progresión dramática, control del ritmo del conflicto', '["La escalada es cómica, no dramática"]'::jsonb, null, null, null, null, true, 58, null),
  ('60', 'Círculo de historias', 'juego', 12, 'grupo', 'Historia colectiva donde cada persona continúa la frase anterior.', '["Sentados en círculo","Primera persona empieza una historia con una frase","Cada persona añade una frase que continúe la lógica","Dar dos o tres vueltas completas"]'::jsonb, 'Narrativa colaborativa, aceptación rápida', '["Con un género literario forzado"]'::jsonb, null, null, null, null, true, 59, null),
  ('61', 'El experto entrevistado', 'juego', 12, 'grupo', 'Un personaje experto en un tema absurdo responde preguntas del público.', '["El público propone la especialidad absurda","Un voluntario se sienta como experto","El resto hace preguntas serias","El experto responde con total convicción"]'::jsonb, 'Compromiso, rapidez mental, humor', '["Dos expertos que se contradicen entre sí"]'::jsonb, null, null, null, null, true, 60, null),
  ('62', 'Alfabeto en escena', 'juego', 15, 'parejas', 'Cada frase de la escena empieza por la siguiente letra del abecedario.', '["Pareja en escena con una situación simple","Primera frase empieza por A, la siguiente por B","Continuar en orden hasta donde se pueda","Mantener el sentido de la escena a la vez"]'::jsonb, 'Rapidez verbal, coherencia bajo restricción', '["Empezar por una letra elegida por el público"]'::jsonb, null, null, null, null, true, 61, null),
  ('63', 'Objeto misterioso', 'juego', 10, 'grupo', 'Adivinar un objeto imaginario a través de cómo lo usan los demás.', '["Una persona sale de la sala","El grupo decide un objeto imaginario","Los demás lo usan en mímica sin nombrarlo","La persona vuelve e intenta adivinarlo"]'::jsonb, 'Mimo, observación, deducción', '["El objeto cambia de función cada vez que se usa"]'::jsonb, null, null, null, null, true, 62, null),
  ('64', 'Doblaje en vivo', 'juego', 15, 'parejas', 'Un actor mueve la boca, otra persona pone la voz en tiempo real.', '["A actúa en silencio moviendo solo la boca","B, detrás o al lado, pone la voz improvisada","Deben sincronizarse sin ensayo previo","Cambiar de roles"]'::jsonb, 'Sincronía, escucha, comedia física', '["Doblaje de una escena muda clásica"]'::jsonb, null, null, null, null, true, 63, null),
  ('65', 'Sillas cambiantes', 'juego', 15, 'grupo', 'Tres sillas y una conversación que cambia de tema al cambiar de silla.', '["Tres actores sentados en sillas distintas","Cada silla representa un tema o tono distinto","Al cambiar de silla cambia también el registro","Mantener la lógica de personaje en cada cambio"]'::jsonb, 'Versatilidad, transición, estructura', '["Las sillas representan personajes distintos, no temas"]'::jsonb, null, null, null, null, true, 64, null),
  ('66', 'El traductor', 'juego', 12, 'grupo', 'Un personaje habla en idioma inventado, otro lo traduce de forma disparatada.', '["A habla en gromelot (idioma inventado) con emoción clara","B traduce al público lo que ''dice''","La traducción puede contradecir el tono físico","Cambiar de roles"]'::jsonb, 'Expresividad no verbal, comedia, contraste', '["El traductor traduce mal a propósito"]'::jsonb, null, null, null, null, true, 65, null),
  ('67', 'Freeze tag', 'juego', 15, 'grupo', 'Dos personas en escena; alguien grita ''congela'' y reemplaza a una en la misma postura.', '["Dos actores empiezan una escena libre","En cualquier momento alguien grita ''¡congela!''","Entra, toca a uno de los dos y ocupa su postura exacta","Empieza una escena nueva justificando esa postura"]'::jsonb, 'Justificación física, ritmo, variedad de escenas', '["Solo se puede congelar en momentos de alta energía"]'::jsonb, null, null, null, null, true, 66, null),
  ('68', 'Narrador saboteador', 'juego', 15, 'grupo', 'Un narrador cuenta la historia y los actores deben obedecer, aunque sea absurdo.', '["Dos o tres actores en escena","Un narrador describe lo que hacen y sienten","Los actores deben ejecutarlo literalmente","El narrador puede complicar la situación a propósito"]'::jsonb, 'Obediencia creativa, aceptación bajo presión', '["Los actores pueden vetar UNA orden por escena"]'::jsonb, null, null, null, null, true, 67, null),
  ('69', 'Emociones en el sombrero', 'juego', 12, 'grupo', 'Escena libre donde cada actor saca una emoción escrita al azar.', '["Preparar papeles con emociones distintas","Cada actor coge uno sin enseñarlo","Improvisan una escena manteniendo su emoción secreta","El público intenta adivinar las emociones de cada uno"]'::jsonb, 'Compromiso emocional, contraste de personajes', '["Las emociones cambian a mitad de escena"]'::jsonb, null, null, null, null, true, 68, null),
  ('70', 'Historia con obstáculos', 'juego', 15, 'grupo', 'Un cuentacuentos es interrumpido por objetos o palabras que el público lanza.', '["Una persona narra una historia improvisada","El público puede gritar un objeto o palabra en cualquier momento","El narrador debe incorporarlo sin frenar la historia","Continuar hasta un cierre razonable"]'::jsonb, 'Flexibilidad narrativa, rapidez, aceptación', '["Dos narradores se turnan la historia"]'::jsonb, null, null, null, null, true, 69, null),
  ('71', 'El juicio absurdo', 'juego', 18, 'grupo', 'Un juicio improvisado sobre una acusación disparatada.', '["El público propone la acusación absurda","Se reparten roles: juez, acusado, fiscal, defensa, testigos","Improvisar el juicio con lógica interna seria","El jurado (resto del grupo) da un veredicto"]'::jsonb, 'Roles definidos, argumentación, comedia', '["El juez es notoriamente parcial"]'::jsonb, null, null, null, null, true, 70, null),
  ('72', 'Formato: La Ronda', 'formato', 30, 'grupo', 'Escenas cortas conectadas por una palabra o imagen que se repite y transforma.', '["Sugerencia inicial del público","Primera escena corta que termina en una imagen o palabra fuerte","La siguiente escena arranca de esa misma imagen, resignificada","Encadenar 5-8 escenas hasta cerrar el círculo temático"]'::jsonb, 'Asociación, transición, unidad temática', '["Cerrar volviendo a la primera escena"]'::jsonb, null, 'Estrutura tomada de «Reigen» (1897), de Arthur Schnitzler', null, null, true, 71, null),
  ('73', 'Formato: Deconstrucción', 'formato', 35, 'grupo', 'Una escena se repite varias veces, cada vez desde un ángulo o género distinto.', '["Escena base corta y simple","Repetirla como tragedia","Repetirla como comedia","Repetirla como thriller o musical"]'::jsonb, 'Versatilidad de género, extracción de la esencia dramática', '["El público elige el género en cada repetición"]'::jsonb, null, null, null, null, true, 72, null),
  ('74', 'Formato: Monólogo a escenas', 'formato', 30, 'grupo', 'Un monólogo personal real da pie a escenas inspiradas libremente en él.', '["Un actor cuenta una anécdota o reflexión personal","El grupo escucha detalles, temas y emociones","A partir de ahí, improvisan escenas libres inspiradas (no literales)","Cerrar volviendo brevemente al monologuista"]'::jsonb, 'Inspiración personal, la Harold clásica de Close/Halpern', '["Varios monólogos cortos en vez de uno largo"]'::jsonb, null, null, null, null, true, 73, null),
  ('75', 'Formato: La espiral', 'formato', 25, 'grupo', 'Escenas que se acortan progresivamente hasta quedar en gestos puros.', '["Primera escena de 3 minutos con arranque y final claros","Repetir la misma historia en 90 segundos","Repetir en 30 segundos","Repetir en un solo gesto o imagen"]'::jsonb, 'Síntesis, esencia dramática, ritmo', '["La espiral se hace al revés, de menos a más"]'::jsonb, null, null, null, null, true, 74, null),
  ('76', 'Formato: Living newspaper', 'formato', 40, 'grupo', 'El público aporta titulares de noticias reales o inventadas y se improvisan escenas sobre ellas.', '["Recoger 3-5 titulares del público","Elegir uno y crear una escena a partir de él","Puede jugarse como reportaje, dramatización o sátira","Repetir con los demás titulares"]'::jsonb, 'Actualidad, sátira, versatilidad temática', '["Formato de telediario con presentador"]'::jsonb, null, null, null, null, true, 75, null),
  ('77', 'Musical: Estribillo colectivo', 'musical', 15, 'grupo', 'El grupo crea un estribillo simple que reaparece a lo largo de la escena.', '["Definir una melodía y frase muy simples entre todos","Iniciar una escena libre","El estribillo aparece cuando algo lo justifica emocionalmente","Cerrar la escena con el estribillo final"]'::jsonb, 'Cohesión musical, callback melódico', '["El estribillo cambia de letra pero no de melodía"]'::jsonb, null, null, null, null, true, 76, null),
  ('78', 'Musical: Ópera de bolsillo', 'musical', 15, 'parejas', 'Una escena cotidiana cantada íntegramente, sin texto hablado.', '["Situación cotidiana simple (pedir un café, discutir por el mando)","Todo el diálogo se canta, sin hablar en ningún momento","Un pianista o beatbox de apoyo si es posible","Mantener la lógica de la escena por encima de la melodía"]'::jsonb, 'Compromiso vocal, humor, sostenimiento de la ficción cantada', '["Estilo ópera trágica en vez de cotidiana"]'::jsonb, null, null, null, null, true, 77, null),
  ('79', 'Musical: Vamp y personaje', 'musical', 12, 'grupo', 'Un acompañamiento repetitivo (vamp) sostiene la entrada y canción de cada personaje.', '["Establecer un vamp simple y repetible (con voz o instrumento)","Cada personaje entra a la escena sobre el vamp","Cuando le toca, canta una estrofa sobre su situación","Vuelta al vamp para la siguiente entrada"]'::jsonb, 'Estructura musical, entradas y salidas con gracia', '["El vamp cambia de tono según el personaje"]'::jsonb, null, null, null, null, true, 78, null),
  ('80', 'Respiración compartida', 'pausa', 4, 'grupo', 'Respiración sincronizada de grupo para bajar revoluciones entre bloques.', '["Círculo, ojos cerrados opcional","Inhalar 4 tiempos, sostener 4, exhalar 4","Repetir 6-8 ciclos en silencio","Abrir los ojos lentamente al terminar"]'::jsonb, 'Regulación de energía, transición entre bloques', '["Con sonido suave al exhalar"]'::jsonb, null, null, null, null, true, 79, null),
  ('81', 'Estiramiento en pareja', 'pausa', 6, 'parejas', 'Estiramientos suaves asistidos para liberar tensión física.', '["Parejas se colocan espalda con espalda","Estirar brazos y torso apoyándose mutuamente","Cambiar de postura cada 30 segundos","Terminar con un agradecimiento silencioso"]'::jsonb, 'Relajación física, conexión no verbal', '["En trío para grupos impares"]'::jsonb, null, null, null, null, true, 80, null),
  ('82', 'Silencio activo', 'pausa', 3, 'grupo', 'Un minuto de silencio total de pie, sin moverse, antes de retomar.', '["Todo el grupo de pie, quieto","Silencio absoluto durante 60 segundos","Notar sonidos del espacio, la respiración propia","Retomar con una palabra en voz baja cada uno"]'::jsonb, 'Presencia, reseteo mental', '["Sentados en vez de de pie"]'::jsonb, null, null, null, null, true, 81, null),
  ('83', 'Agua y estiramiento libre', 'pausa', 5, 'grupo', 'Pausa funcional para beber agua y estirar libremente antes de retomar.', '["Anunciar 5 minutos de pausa libre","Beber agua, estirar, hablar en voz baja si se quiere","Aviso a los 4 minutos para volver","Reagrupar en círculo para retomar"]'::jsonb, 'Descanso físico real, prevención de fatiga', '["Con música ambiental de fondo"]'::jsonb, null, null, null, null, true, 82, null),
  ('84', 'Cierre: Rueda de aplausos', 'cierre', 5, 'grupo', 'Cada persona recibe un aplauso individual y específico del grupo.', '["Círculo","Cada persona pasa al centro brevemente","El resto aplaude mirándola directamente","Vuelve al círculo y pasa la siguiente"]'::jsonb, 'Reconocimiento individual, cierre cálido', '["Con una palabra de despedida por persona"]'::jsonb, null, null, null, null, true, 83, null),
  ('85', 'Cierre: La última imagen', 'cierre', 6, 'grupo', 'El grupo crea una imagen congelada colectiva que resume la sesión.', '["Sin hablar, cada persona entra a un espacio central","Añade su cuerpo a una composición grupal","Todos deciden cuándo la imagen está completa","Mantener 10 segundos antes de romper"]'::jsonb, 'Síntesis no verbal, cohesión final', '["La imagen representa una palabra elegida antes"]'::jsonb, null, null, null, null, true, 84, null),
  ('86', 'Cierre: Carta breve', 'cierre', 8, 'grupo', 'Escribir una frase corta a uno mismo sobre lo trabajado hoy.', '["Cada persona coge papel y boli","Escribe una frase breve dirigida a sí misma","Se guarda, no se comparte (a menos que se quiera)","Cierre con un aplauso colectivo"]'::jsonb, 'Reflexión personal, cierre introspectivo', '["Se comparte en voz alta de forma voluntaria"]'::jsonb, null, null, null, null, true, 85, null),
  ('87', 'Yes-and en cadena', 'juego', 10, 'grupo', 'Frase iniciada por una persona, continuada por todo el grupo en cadena de ''sí, y...''.', '["Una persona lanza una frase inicial","La siguiente responde con ''Sí, y...'' añadiendo información","Continuar en círculo sin romper la lógica","Cerrar cuando la historia llegue a un punto natural"]'::jsonb, 'Aceptación en cadena, construcción colectiva', '["Con ''Sí, pero...'' para explorar el conflicto"]'::jsonb, null, null, null, null, true, 86, null),
  ('88', 'El objeto que no es', 'juego', 10, 'grupo', 'Un objeto cotidiano se usa deliberadamente mal, en su función incorrecta.', '["Circula un objeto real (una silla, un vaso)","Cada persona lo usa para algo que no es","Debe quedar claro el nuevo uso sin explicarlo","Dar una vuelta completa"]'::jsonb, 'Creatividad, mimo, ruptura de patrones', '["El objeto imaginario cambia de tamaño con cada uso"]'::jsonb, null, null, null, null, true, 87, null),
  ('89', 'Escena en reversa', 'entrenamiento', 15, 'parejas', 'Jugar una escena y después repetirla exactamente al revés.', '["Escena corta con inicio y final claros","Anotar mentalmente la secuencia de acciones","Repetir la escena empezando por el final","Mantener coherencia de personaje en la inversión"]'::jsonb, 'Memoria de escena, estructura, control', '["Solo el texto se invierte, no la acción física"]'::jsonb, null, null, null, null, true, 88, null),
  ('90', 'Diálogo de una palabra', 'juego', 10, 'parejas', 'Conversación completa donde cada persona solo puede decir una palabra por turno.', '["Pareja en escena con una situación simple","Cada turno de habla es una sola palabra","Construir sentido a través de la sucesión","Mantener 3-4 minutos"]'::jsonb, 'Precisión, escucha extrema, economía verbal', '["Máximo dos palabras por turno"]'::jsonb, null, null, null, null, true, 89, null),
  ('91', 'Círculo de estatus', 'entrenamiento', 18, 'grupo', 'Entradas y salidas de un espacio común jugando estatus alto o bajo asignado.', '["Espacio neutro compartido (una sala de espera, por ejemplo)","Cada persona entra con un estatus asignado en secreto","Interactúan libremente manteniendo su estatus","El grupo comenta las jerarquías percibidas al final"]'::jsonb, 'Status, dinámica grupal, observación', '["El estatus de cada uno cambia a media escena"]'::jsonb, null, null, null, null, true, 90, null),
  ('92', 'La foto familiar', 'juego', 12, 'grupo', 'El grupo compone una foto familiar disfuncional y la anima brevemente.', '["El público propone el tipo de familia (rara, famosa, de otra época)","El grupo compone la pose fotográfica congelada","A la señal, la imagen cobra vida 15 segundos","Vuelve a congelarse para ''la foto''"]'::jsonb, 'Composición grupal, caracterización rápida', '["Varias fotos familiares consecutivas, distintas décadas"]'::jsonb, null, null, null, null, true, 91, null),
  ('93', 'El eco emocional', 'calentamiento', 8, 'grupo', 'Una frase se repite en círculo cambiando de emoción cada vez.', '["Elegir una frase neutra simple","Primera persona la dice con una emoción","La siguiente la repite con una emoción distinta","Dar una vuelta completa sin repetir emoción"]'::jsonb, 'Rango emocional, escucha, variedad expresiva', '["La frase también cambia de idioma inventado"]'::jsonb, null, null, null, null, true, 92, null),
  ('94', 'Formato: El árbol genealógico', 'formato', 35, 'grupo', 'Escenas que saltan entre generaciones de una misma familia inventada.', '["Crear el personaje fundador de la familia","Escena de su vida en una época concreta","Saltar a la generación siguiente con un actor distinto","Repetir hasta llegar al presente, buscando ecos y patrones"]'::jsonb, 'Estructura temporal larga, herencia temática', '["El público elige el salto temporal en cada ronda"]'::jsonb, null, null, null, null, true, 93, null),
  ('95', 'Formato: Preguntas y respuestas', 'formato', 25, 'grupo', 'El público hace preguntas a un personaje que después se convierten en escenas.', '["Un actor se presenta como un personaje concreto","El público le hace preguntas libres","Cada respuesta interesante se convierte en una escena corta","Volver al personaje entre escena y escena"]'::jsonb, 'Escucha del público, generación de material', '["Dos personajes responden preguntas de forma cruzada"]'::jsonb, null, null, null, null, true, 94, null),
  ('96', 'Statues vivientes', 'juego', 10, 'grupo', 'El grupo se mueve como estatuas que solo cambian de postura cuando nadie las mira.', '["Todos en posiciones de estatua por el espacio","Un ''guardián'' se da la vuelta y observa al azar","Si alguien se mueve al ser visto, se congela definitivamente","El último en moverse gana la ronda"]'::jsonb, 'Control corporal, atención, juego físico', '["Las estatuas deben representar un tema concreto"]'::jsonb, null, null, null, null, true, 95, null),
  ('97', 'Traducción simultánea inversa', 'juego', 12, 'parejas', 'Un actor habla en español, otro ''traduce'' a gromelot con la misma emoción.', '["A habla normalmente sobre cualquier tema","B traduce simultáneamente a un idioma inventado","Mantener el tono y ritmo del original","Cambiar de roles a mitad"]'::jsonb, 'Escucha de tono, expresividad vocal', '["La traducción es deliberadamente incoherente"]'::jsonb, null, null, null, null, true, 96, null),
  ('98', 'El objeto heredado', 'entrenamiento', 15, 'grupo', 'Un objeto simbólico pasa de escena en escena cambiando de significado.', '["Definir un objeto físico simple (una caja, un pañuelo)","Primera escena corta donde el objeto tiene un significado","Segunda escena distinta donde el mismo objeto significa otra cosa","Repetir 3-4 veces, notando la evolución del símbolo"]'::jsonb, 'Simbolismo, reincorporación, coherencia de objeto', '["El objeto es invisible, solo mímico"]'::jsonb, null, null, null, null, true, 97, null),
  ('99', 'Coro griego', 'formato', 20, 'grupo', 'Un coro comenta, amplifica y comenta la acción de los protagonistas.', '["Dos o tres actores hacen la escena principal","El resto del grupo actúa como coro alrededor","El coro puede hablar al unísono, comentar o mover la escena","Mantener la convención coro/protagonistas todo el tiempo"]'::jsonb, 'Trabajo coral, amplificación dramática', '["El coro solo puede usar sonidos, no palabras"]'::jsonb, null, null, null, null, true, 98, null),
  ('100', 'El curriculum imposible', 'juego', 12, 'grupo', 'Entrevista de trabajo para un puesto absurdo con un candidato convencido de ser perfecto.', '["El público propone el puesto de trabajo absurdo","Un actor es el entrevistador, otro el candidato","El candidato justifica con total seguridad su idoneidad","El entrevistador decide si lo contrata al final"]'::jsonb, 'Compromiso, justificación, status', '["Varios candidatos compiten por el mismo puesto"]'::jsonb, null, null, null, null, true, 99, null),
  ('101', 'Cambio de canal', 'juego', 15, 'grupo', 'Una escena salta entre distintos géneros de televisión al ''cambiar de canal''.', '["Definir 4-5 géneros de TV (telenovela, documental, deportes, anuncio)","Escena base sencilla en curso","Alguien grita ''clic'' y la escena salta de género manteniendo el tema","Volver al canal original para cerrar"]'::jsonb, 'Versatilidad de género, transición rápida', '["El público controla el mando a distancia"]'::jsonb, null, null, null, null, true, 100, null),
  ('102', '185 [X] entran en un bar', 'juego', 10, 'grupo', 'Juego de chistes rápidos con una estructura fija y un plural propuesto por el público.', '["Pedir al público un sustantivo en plural (pingüinos, dentistas, farolas)","Los jugadores se colocan en fila","Uno da un paso al frente y dice: ''185 [X] entran en un bar. El camarero dice: no servimos a [X]''","Cierra con un remate que juegue con la palabra","Volver a la fila y pasar al siguiente"]'::jsonb, 'Agilidad verbal, juego de palabras, aceptación del fracaso', '["Sin pausas: encadenar sin dejar silencio","Prohibido repetir el mismo tipo de chiste"]'::jsonb, null, null, null, 'improvgames.com', true, 101, null),
  ('103', 'Manos ajenas', 'juego', 12, 'parejas', 'Un actor presta sus brazos a otro, que queda con las manos a la espalda.', '["A se coloca delante con los brazos a la espalda","B se sitúa detrás y pasa sus brazos bajo las axilas de A","B hace todos los gestos y manipula los objetos; A habla","Elegir una escena que requiera manipular cosas: cocinar, maquillarse, arreglar algo","A justifica todo lo que hagan las manos, sin corregir a B"]'::jsonb, 'Coordinación, aceptación, comedia física', '["Dos parejas de manos ajenas en la misma escena","B también puede hablar, doblando a A"]'::jsonb, null, null, null, 'improvgames.com', true, 102, null),
  ('104', 'Partes del cuerpo', 'entrenamiento', 10, 'parejas', 'La escena arranca desde un contacto físico concreto que hay que justificar.', '["El público o el facilitador nombra dos partes del cuerpo","Los dos actores se colocan en contacto por esas dos partes","Empezar la escena desde esa postura, sin explicarla","Justificar el contacto de forma natural en los primeros segundos","Cambiar de posición cuando se pida otra pareja de partes"]'::jsonb, 'Justificación, escucha física, arranque sin planificar', '["Cambiar la posición cada 30 segundos sin cortar la escena","Tres actores, tres puntos de contacto"]'::jsonb, null, null, null, 'improvgames.com', true, 103, null),
  ('105', 'Rima obligada', 'juego', 12, 'grupo', 'En mitad de la escena alguien exige que se rime, y los actores continúan en verso.', '["Empezar una escena normal","El facilitador grita ''¡rima!'' en cualquier momento","Los actores siguen la escena rimando cada réplica","Al oír ''¡corta!'' se vuelve a la prosa","Alternar varias veces durante la escena"]'::jsonb, 'Agilidad verbal, sostener la historia bajo presión', '["Solo rima uno de los personajes","Toda la escena rimada de principio a fin"]'::jsonb, null, null, null, 'improvgames.com', true, 104, null),
  ('106', 'Por suerte / por desgracia', 'calentamiento', 8, 'grupo', 'Una historia colectiva que alterna golpes de suerte y desgracias.', '["Círculo de pie","El primero empieza con una frase cualquiera","El siguiente empieza obligatoriamente por ''por suerte...''","El siguiente por ''por desgracia...''","Alternar por todo el círculo sin romper la historia"]'::jsonb, 'Construcción colectiva, aceptación, narrativa', '["Buenas noticias / malas noticias","Añadir una tercera opción: ''y además...''"]'::jsonb, null, null, null, 'improvgames.com', true, 105, null),
  ('107', 'Convergencia', 'calentamiento', 6, 'grupo', 'Dos personas intentan llegar a la misma palabra a la vez, ronda tras ronda.', '["Dos jugadores frente a frente","A la de tres, cada uno dice una palabra cualquiera","A la de tres otra vez, ambos dicen una palabra que conecte las dos anteriores","Repetir hasta que los dos digan exactamente la misma palabra","Celebrar y cambiar de pareja"]'::jsonb, 'Sintonía, pensamiento asociativo, mente de grupo', '["Todo el grupo a la vez, buscando una palabra común","Sin hablar entre rondas"]'::jsonb, null, null, null, 'improvgames.com', true, 106, null),
  ('108', 'Cuento antes de dormir', 'juego', 12, 'grupo', 'Alguien lee un cuento de un libro invisible mientras el resto lo representa.', '["Un actor se sienta con un libro imaginario","El público propone un título absurdo","El lector improvisa el cuento en voz alta","El resto del grupo representa lo que va narrando, sin adelantarse","El lector puede reaccionar a lo que hacen y reincorporarlo"]'::jsonb, 'Narración, escucha, trabajo mudo de apoyo', '["El niño que escucha interrumpe con preguntas","Dos lectores que se contradicen"]'::jsonb, null, null, null, 'improvgames.com', true, 107, null),
  ('109', 'Muerte en un minuto', 'juego', 10, 'grupo', 'Escena con cuenta atrás en la que todos los personajes deben morir al acabar el tiempo.', '["El público propone un lugar","Poner un temporizador visible de un minuto","Jugar una escena normal, sin forzar el final","Todos los personajes deben haber muerto justo al llegar a cero","Las muertes tienen que estar justificadas por la historia"]'::jsonb, 'Gestión del tiempo, estructura, compromiso', '["Treinta segundos","Muertes en orden inverso al de aparición"]'::jsonb, null, null, null, 'improvgames.com', true, 108, null),
  ('110', 'Diccionario', 'juego', 12, 'grupo', 'Un actor tiene que conseguir que su compañero diga una palabra secreta.', '["Elegir en secreto una palabra poco común y enseñársela al público","Empezar una escena cotidiana","A intenta que B diga esa palabra sin nombrarla ni señalarla","B no sabe cuál es y juega la escena con normalidad","La escena acaba cuando B la dice"]'::jsonb, 'Objetivo oculto, escucha, paciencia escénica', '["Los dos actores tienen palabra secreta","El público avisa con un sonido cuando se acercan"]'::jsonb, null, null, null, 'improvgames.com', true, 109, null),
  ('111', 'Ding', 'entrenamiento', 12, 'grupo', 'Al sonar una campana, el actor debe repetir su última frase cambiándola por otra.', '["Escena en curso entre dos actores","El facilitador toca una campana justo después de una réplica","El actor repite la frase con otra opción completamente distinta","Puede sonar varias veces seguidas sobre la misma réplica","Seguir con la opción que quede tras el último ding"]'::jsonb, 'Descartar la primera idea, flexibilidad, riesgo', '["Ding emocional: cada ding intensifica la emoción","El público toca la campana"]'::jsonb, null, null, null, 'improvgames.com', true, 110, null),
  ('112', 'Comentario del director', 'juego', 12, 'grupo', 'Una escena con la pista de audio del director comentando el rodaje.', '["Dos actores juegan una escena","Otro actor, fuera de escena, comenta como en los extras de un DVD","Habla de presupuesto, anécdotas del rodaje, actores difíciles","Los de la escena no oyen los comentarios pero los actores pueden justificarlos","Alternar comentario y escena"]'::jsonb, 'Perspectiva, humor de contraste, escucha desde fuera', '["Dos comentaristas que se contradicen","El comentario es de un crítico que odia la película"]'::jsonb, null, null, null, 'improvgames.com', true, 111, null),
  ('113', 'Destilación', 'entrenamiento', 15, 'grupo', 'La misma escena se repite cada vez más corta hasta quedar en su esencia.', '["Jugar una escena completa de unos tres minutos","Repetirla en un minuto, conservando lo esencial","Repetirla en treinta segundos","Repetirla en diez segundos","Cerrar con una versión de tres segundos"]'::jsonb, 'Reincorporación, memoria, identificar el núcleo de una escena', '["Cada repetición en un género distinto","La última versión sin palabras"]'::jsonb, null, null, null, 'improvgames.com', true, 112, null),
  ('114', 'Doble vida', 'juego', 12, 'parejas', 'Una escena muy breve se repite después revelando lo que cada personaje pensaba.', '["Jugar una escena de veinte segundos, muy simple","Repetirla exactamente igual","Esta vez, cada actor dice en voz alta su pensamiento antes de cada frase","El pensamiento debe contradecir o complicar lo que dice","Cerrar comparando las dos versiones"]'::jsonb, 'Subtexto, doble lectura, construcción de personaje', '["Otro actor pone la voz de los pensamientos","Tres versiones: dicha, pensada y deseada"]'::jsonb, null, null, null, 'improvgames.com', true, 113, null),
  ('115', 'El portavoz', 'juego', 12, 'grupo', 'Un solo actor pone la voz a todos los personajes de la escena.', '["Dos o tres actores se mueven y actúan en escena, en silencio","Un cuarto actor, a un lado, habla por todos ellos","Los de escena deben ajustar su cuerpo a lo que se dice","El portavoz debe seguir lo que hacen, no imponerlo","Cambiar de portavoz a mitad de escena"]'::jsonb, 'Escucha bidireccional, cesión de control', '["Dos portavoces, uno por personaje","El portavoz está de espaldas al escenario"]'::jsonb, null, null, null, 'improvgames.com', true, 114, null),
  ('116', 'Sinfonía emocional', 'juego', 10, 'grupo', 'Un director orquesta emociones en lugar de instrumentos.', '["Los actores se colocan en fila como un coro","Cada uno recibe una emoción distinta","Un director señala a quién le toca expresarse","Al señalar, ese actor sube el volumen de su emoción; al bajar la mano, la baja","Combinar varios a la vez para crear la sinfonía"]'::jsonb, 'Rango emocional, control de intensidad, trabajo coral', '["Sin palabras, solo sonido","Las emociones cambian a mitad de partida"]'::jsonb, null, null, null, 'improvgames.com', true, 115, null),
  ('117', 'Noticias de cuento', 'juego', 15, 'grupo', 'Una noticia reciente se cruza con un cuento clásico.', '["El público propone una noticia de actualidad","El público propone un cuento tradicional","Los actores mezclan ambos en una sola escena","Los personajes del cuento reaccionan al conflicto de la noticia","Cerrar con la moraleja del cuento aplicada a la noticia"]'::jsonb, 'Asociación, referencia cultural, sátira', '["Formato telediario","Tres cuentos encadenados"]'::jsonb, null, null, null, 'improvgames.com', true, 116, null),
  ('118', 'Dedos', 'entrenamiento', 8, 'parejas', 'Improvisar con dos dedos sobre una mesa en lugar de con todo el cuerpo.', '["Cada jugador apoya dos dedos sobre la mesa: son su personaje","Los dedos caminan, se sientan, corren y se enfrentan","La escena se juega solo con la voz y el movimiento de los dedos","Probar acciones difíciles: bailar, pelear, despedirse","Comentar después qué se hizo distinto al no tener cuerpo"]'::jsonb, 'Perder el pudor, atrevimiento, economía de recursos', '["Sin voz, solo movimiento","Un dedo por actor, escena de grupo"]'::jsonb, null, null, null, 'improvgames.com', true, 117, null),
  ('119', 'Teatro de linterna', 'juego', 12, 'grupo', 'La escena ocurre a oscuras y solo se ve lo que ilumina una linterna.', '["Apagar las luces de sala","Un actor maneja una linterna desde fuera de escena","Solo existe lo que está iluminado","Los actores entran y salen del haz de luz","La linterna decide el ritmo y el foco de la escena"]'::jsonb, 'Foco, control del espacio, tensión', '["Dos linternas","Los propios actores se iluminan entre ellos"]'::jsonb, null, null, null, 'improvgames.com', true, 118, null),
  ('120', 'Bifurcación', 'juego', 15, 'grupo', 'La escena se detiene en un punto y se prueban dos caminos distintos.', '["Empezar una escena normal","Al minuto, el director la para en un momento de decisión","Se rebobina y se juega la otra opción posible","Comparar hacia dónde va cada versión","Elegir una de las dos y llevarla hasta el final"]'::jsonb, 'Conciencia de las decisiones dramáticas, estructura', '["Tres caminos en vez de dos","El público elige qué rama continuar"]'::jsonb, null, null, null, 'improvgames.com', true, 119, null),
  ('121', 'Mercadillo', 'juego', 12, 'grupo', 'Varios actores son objetos de un mercadillo y uno los examina.', '["Los actores se colocan como objetos en venta, congelados","Un jugador entra como comprador","Al tocar un objeto, este cobra vida y se presenta","El comprador regatea o pregunta","El objeto vuelve a congelarse cuando lo suelta"]'::jsonb, 'Objeto imaginario, creatividad, transformación', '["Los objetos tienen historia previa entre ellos","El comprador solo puede llevarse uno"]'::jsonb, null, null, null, 'improvgames.com', true, 120, null),
  ('122', 'Canción dirigida', 'musical', 12, 'grupo', 'Un director decide en cada momento quién canta la improvisación.', '["El grupo en fila, un director delante","Establecer un tema o un estribillo sencillo","El director señala a un cantante y ese continúa la canción","Al cambiar de señalado, el nuevo debe seguir sin romper la letra ni el ritmo","Cerrar con todos cantando a la vez"]'::jsonb, 'Escucha musical, continuidad, atención', '["Señalar a dos a la vez, en dúo","Cambios muy rápidos, cada dos palabras"]'::jsonb, null, null, null, 'improvgames.com', true, 121, null),
  ('123', 'Bucle de poses', 'calentamiento', 8, 'grupo', 'Los jugadores van añadiendo poses que completan la imagen anterior.', '["Uno entra y adopta una pose cualquiera","Otro entra y añade una pose que complemente la primera","Sigue un tercero, y un cuarto","Cuando la imagen esté llena, el primero sale y explica qué era","Los demás recolocan la imagen a partir de lo que queda"]'::jsonb, 'Imagen de grupo, aceptación visual, composición', '["En silencio total","Cada pose con un sonido asociado"]'::jsonb, null, null, null, 'improvgames.com', true, 122, null),
  ('124', 'Concentración impro', 'calentamiento', 10, 'grupo', 'Versión impro del juego de memoria por parejas, con gestos en lugar de cartas.', '["Formar parejas y acordar en secreto un gesto con sonido compartido","Todos se dispersan por la sala","Un jugador señala a dos personas cualesquiera","Ambas hacen su gesto: si coinciden, esa pareja sale","Continuar hasta que queden pocas parejas"]'::jsonb, 'Memoria, atención grupal, energía', '["Con emociones en vez de gestos","Las parejas cambian de gesto a mitad de juego"]'::jsonb, null, null, null, 'improvgames.com', true, 123, null),
  ('125', 'Bailar para tu pareja', 'calentamiento', 8, 'parejas', 'Un jugador baila con el único objetivo de que su pareja disfrute.', '["Por parejas, uno baila y el otro observa","El que baila busca provocar alegría en el otro, no lucirse","El que observa responde con sinceridad, sin fingir","Cambiar de rol a los dos minutos","Comentar qué cambia cuando el objetivo es el otro"]'::jsonb, 'Generosidad escénica, atención al compañero', '["Con música elegida por el que observa","En grupos de cuatro"]'::jsonb, null, null, null, 'improvgames.com', true, 124, null),
  ('126', '¿Sabes qué me gusta de ti?', 'cierre', 10, 'parejas', 'Ejercicio de cierre en el que cada persona nombra algo real que valora del otro.', '["Formar parejas","A dice: ''¿sabes qué me gusta de ti?'' y completa con algo concreto y verdadero","B solo responde ''gracias'', sin devolver el cumplido ni restarle importancia","Cambiar de rol","Rotar parejas dos o tres veces"]'::jsonb, 'Confianza, cohesión, cerrar en positivo', '["En círculo, dirigido a quien está a la derecha","Referido a algo que pasó en la sesión de hoy"]'::jsonb, null, null, null, 'improvgames.com', true, 125, null),
  ('127', 'Hoguera', 'cierre', 10, 'grupo', 'El grupo se sienta alrededor de una hoguera imaginaria para cerrar la sesión.', '["Sentarse en círculo alrededor de una hoguera invisible","Bajar la luz si es posible","Cada persona comparte un momento de la sesión que se lleva","Se puede hablar solo cuando se tiene la mirada del grupo","Cerrar apagando la hoguera entre todos"]'::jsonb, 'Reflexión, cierre emocional, comunidad', '["Cada uno echa al fuego algo que deja atrás","En silencio, solo con gestos"]'::jsonb, null, null, null, 'improvgames.com', true, 126, null),
  ('128', 'Asesinato con cartas', 'juego', 20, 'grupo', 'Misterio de asesinato en el que una baraja reparte el estatus en secreto.', '["Repartir una carta a cada actor sin que la vea nadie más","El número marca el estatus del personaje: as el más bajo, rey el más alto","Una carta concreta, acordada de antemano, designa al asesino","Jugar la escena de misterio con los estatus en juego","Al final, el público adivina quién tenía cada carta"]'::jsonb, 'Estatus, sostener información oculta, tensión', '["Los actores no ven su propia carta y la llevan en la frente","Sin asesino: solo el juego de estatus"]'::jsonb, null, null, null, 'improvgames.com', true, 127, null),
  ('129', 'El mensaje del público', 'juego', 12, 'grupo', 'Frases sacadas de los móviles del público se usan como diálogo.', '["Antes de empezar, pedir a varias personas del público un mensaje de su móvil","Recogerlos por escrito o leerlos en directo","Los actores juegan una escena normal","En momentos marcados, un actor debe usar uno de esos mensajes como réplica","Justificar la frase por rara que sea"]'::jsonb, 'Justificación, aceptación de material ajeno', '["Solo un personaje habla con mensajes ajenos","El público lee sus propios mensajes en voz alta"]'::jsonb, null, null, null, 'improvgames.com', true, 128, null),
  ('130', 'El narrador a campana', 'juego', 12, 'grupo', 'Una campana del público decide cuándo un actor pasa a narrar.', '["Dar una campana a alguien del público","Escena normal entre dos o tres actores","Al sonar la campana, el actor que hablaba pasa a narrar en tercera persona","Al sonar de nuevo, vuelve al diálogo","Los demás siguen actuando lo que el narrador cuenta"]'::jsonb, 'Cambio de registro, narración, control externo', '["Dos campanas con funciones distintas","La campana la lleva el facilitador"]'::jsonb, null, null, null, 'improvgames.com', true, 129, null),
  ('131', 'Mejor actor', 'juego', 15, 'grupo', 'Escenas cortas presentadas como nominaciones a un premio de interpretación.', '["El público propone títulos de película inventados","Un presentador anuncia cada nominación","Los actores juegan un fragmento breve de esa película","Repetir con tres o cuatro nominados","El público elige al ganador con aplausos"]'::jsonb, 'Escena corta, compromiso inmediato, variedad', '["Categorías absurdas: mejor secundario mudo, mejor caída","El ganador da discurso de agradecimiento improvisado"]'::jsonb, null, null, null, 'improvgames.com', true, 130, null),
  ('132', 'Doblar el musical', 'musical', 20, 'grupo', 'Un musical improvisado donde las canciones las cantan otros desde fuera.', '["Dos actores hacen la escena y mueven los labios al cantar","Otros dos, fuera de escena, ponen la voz cantada","Los de escena deben ajustar el gesto a lo que oyen","Los de fuera deben seguir la historia que ven","Alternar diálogo hablado y números cantados"]'::jsonb, 'Sincronía, escucha musical, trabajo en equipo', '["Las voces cambian de dueño a mitad de canción","Solo se dobla el estribillo"]'::jsonb, null, null, null, 'improvgames.com', true, 131, null),
  ('133', 'Física emocional', 'entrenamiento', 12, 'parejas', 'La emoción se construye primero desde el cuerpo y después llega el texto.', '["Elegir una emoción sin decirla en voz alta","Recorrer la sala dejando que esa emoción cambie la forma de andar","Exagerar hasta la caricatura y después reducir a un diez por ciento","Con esa física reducida, empezar una escena cotidiana","No nombrar nunca la emoción: solo habitarla"]'::jsonb, 'Emoción encarnada, evitar el cliché verbal', '["Cambiar de emoción sin cortar la escena","Adivinar la emoción del compañero al final"]'::jsonb, null, null, null, 'improvgames.com', true, 132, null),
  ('134', 'Carné de identidad', 'juego', 12, 'grupo', 'Los personajes se construyen con datos reales de documentos del público.', '["Pedir prestados carnés o tarjetas a personas del público","Leer en voz alta un dato: nombre, ciudad, fecha","Cada actor construye un personaje a partir de esos datos","Jugar una escena que los reúna a todos","Devolver los documentos al acabar"]'::jsonb, 'Construcción rápida de personaje, especificidad', '["Solo con la foto, sin leer los datos","El dueño del carné valida o desmiente al final"]'::jsonb, null, null, null, 'improvgames.com', true, 133, null),
  ('135', 'Pilares en otro idioma', 'juego', 12, 'grupo', 'Personas del público colocadas a los lados dictan las frases de los actores.', '["Colocar a dos personas del público a cada lado del escenario","Cuando un actor se acerca a una de ellas, esta le sopla una frase","El actor la dice tal cual y la justifica en la escena","Cuanto más rara la frase, mejor","Alternar de lado varias veces"]'::jsonb, 'Aceptación, justificación, interacción con el público', '["Las frases en otro idioma y el actor las traduce a su manera","Solo un pilar, para un solo personaje"]'::jsonb, null, null, null, 'improvgames.com', true, 134, null),
  ('136', '¿Alguna vez...?', 'calentamiento', 8, 'grupo', 'Historia colectiva construida palabra a palabra a partir de una pregunta.', '["Círculo de pie","Empezar todos juntos: ''¿alguna vez...?''","A partir de ahí, cada persona aporta una sola palabra por turno","No se puede planificar: hay que aceptar la palabra anterior","Cuando la frase se cierre sola, empezar otra"]'::jsonb, 'Escucha, cesión del control, construcción colectiva', '["Dos palabras por persona","La historia debe acabar antes de dar la vuelta completa"]'::jsonb, null, null, null, 'improvgames.com', true, 135, null),
  ('137', 'Formato: Monoescena', 'formato', 30, 'grupo', 'Long form de una sola escena: un único lugar, un único tiempo, sin cortes ni saltos.', '["Pedir al público un lugar concreto","Todos los personajes existen en ese espacio desde el principio","No hay cortes, ni flashbacks, ni cambios de sitio","Los actores entran y salen justificando siempre por qué","La historia avanza solo por lo que ocurre entre los personajes"]'::jsonb, 'Sostener relación y tensión sin recurrir a trucos de edición', '["Monoescena en tiempo real estricto","Con un personaje que no puede irse nunca"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 136, null),
  ('138', 'Formato: La Sibila', 'formato', 25, 'solo', 'Long form para un solo intérprete que encarna a todos los personajes de la historia.', '["Un único actor en escena","Recoger una sugerencia del público","Interpretar a todos los personajes cambiando de posición y de voz","Marcar claramente el espacio de cada personaje para que el público no se pierda","Cerrar reuniendo a todos los personajes en una última imagen"]'::jsonb, 'Claridad de personaje, resistencia, control del espacio', '["Con un músico en directo apoyando los cambios","En pareja: dos solistas alternándose"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 137, null),
  ('139', 'Formato: El murciélago', 'formato', 20, 'grupo', 'Un actor con los ojos vendados juega la escena guiado solo por el sonido.', '["Vendar los ojos a un actor","El resto del grupo se mueve por el espacio en silencio","El actor vendado solo puede orientarse por lo que oye","Los demás pueden hablar, hacer ruidos y moverse alrededor","Cuidar la seguridad: alguien vigila el borde del escenario"]'::jsonb, 'Escucha extrema, confianza, tensión escénica', '["Dos actores vendados","Todo el grupo vendado menos uno"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 138, null),
  ('140', 'Formato: Collar de perlas', 'formato', 30, 'grupo', 'Se juegan primero la primera y la última escena, y después se rellena lo que falta.', '["Jugar la escena inicial de la historia","Jugar la escena final, sin saber cómo se llega hasta ella","Volver atrás y jugar escenas intermedias en cualquier orden","Cada escena nueva debe encajar entre las que ya existen","Repasar mentalmente el collar completo antes de cerrar"]'::jsonb, 'Estructura narrativa, reincorporación, visión de conjunto', '["El público pide en qué hueco se juega la siguiente","Solo cinco perlas exactas"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 139, null),
  ('141', 'Formato: Trenza francesa', 'formato', 35, 'grupo', 'Tres historias independientes que se van cruzando hasta acabar entrelazadas.', '["Abrir tres escenas distintas, sin relación aparente","Alternar entre ellas en fragmentos cortos","A partir de la segunda vuelta, empezar a pasar elementos de una a otra","Un personaje de una historia puede aparecer en otra","Cerrar con las tres historias tocándose en una escena final"]'::jsonb, 'Reincorporación, estructura paralela, paciencia', '["Solo dos hilos","Las tres historias en épocas distintas"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 140, null),
  ('142', 'Formato: Película', 'formato', 35, 'grupo', 'La sesión se juega como un largometraje, con género, títulos de crédito y planos.', '["El público propone género y título","Un actor hace de director y pide planos: primer plano, plano general, cámara lenta","Los actores obedecen los cambios de plano sin salir del personaje","Incluir créditos iniciales y finales","Cerrar con la escena que da título a la película"]'::jsonb, 'Lenguaje cinematográfico, narrativa larga, foco', '["Con banda sonora en directo","Añadir escena post-créditos"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 141, null),
  ('143', 'Formato: Culebrón', 'formato', 30, 'grupo', 'Serie por episodios con giros melodramáticos y cortes en el momento de máxima tensión.', '["Establecer una familia o comunidad con varias relaciones","Jugar episodios cortos de tres o cuatro minutos","Cada episodio corta justo en el momento más tenso","Entre episodios, un narrador resume ''en el capítulo anterior''","El último episodio resuelve al menos dos tramas"]'::jsonb, 'Personajes recurrentes, gestión de tramas, exageración controlada', '["Saltos temporales de años entre episodios","Un personaje vuelve de entre los muertos"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 142, null),
  ('144', 'Formato: Diamante', 'formato', 25, 'grupo', 'Cuatro actores en rombo: solo se ve la escena de los dos que miran al público.', '["Cuatro actores colocados en rombo, mirando hacia fuera","Solo la pareja que da al público está en escena","A una señal, el rombo gira y aparece otra pareja","La escena nueva es distinta pero hereda algo de la anterior","Volver a la primera pareja para cerrar"]'::jsonb, 'Transición limpia, memoria de escena, trabajo geométrico', '["Giros cada vez más rápidos","Las cuatro escenas comparten un mismo objeto"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 143, null),
  ('145', 'Formato: Slacker', 'formato', 30, 'grupo', 'La cámara sigue a un personaje hasta que se cruza con otro, y entonces cambia de protagonista.', '["Empezar siguiendo a un personaje cualquiera","Cuando aparece otro personaje, la atención puede saltar a él","El anterior desaparece de la historia","Encadenar así una cadena de protagonistas","Cerrar volviendo al primero, si es posible"]'::jsonb, 'Fluidez, cesión de protagonismo, cadena narrativa', '["El público decide cuándo saltar","Obligar a volver al inicio en la última escena"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 144, null),
  ('146', 'Formato: Maestro Impro (Micetro)', 'formato', 45, 'grupo', 'Formato competitivo de Keith Johnstone donde el público puntúa cada escena y se van eliminando jugadores.', '["Un director dirige a los improvisadores desde fuera","Se juegan escenas cortas por parejas o tríos","El público puntúa cada escena de uno a cinco","Los de puntuación más baja van quedando eliminados","El último en pie gana la noche"]'::jsonb, 'Escena corta bajo presión, aceptación de la dirección externa', '["Sin eliminación, solo puntuación acumulada","Los eliminados pasan a hacer de apoyo"]'::jsonb, null, 'Keith Johnstone — Loose Moose Theatre, Calgary', '⚠️ Marca rexistrada. Require permiso do International Theatresports Institute (impro.global). Dereitos de produción: 3% da recadación bruta. Existe acordo educativo para centros de ensino.', 'improvencyclopedia.org', true, 145, null),
  ('147', 'Formato: Gorilla Theatre', 'formato', 45, 'grupo', 'Formato de Johnstone en el que los propios improvisadores dirigen por turnos y compiten por un trofeo.', '["Cada improvisador dirige una escena en su turno","El director elige el juego y reparte los papeles, pero no actúa","El público valora si la escena mereció la pena","El director gana o pierde un punto según la reacción","Gana quien acumule más puntos al final"]'::jsonb, 'Dirección, criterio, responsabilidad sobre la escena ajena', '["Sin competición, solo rotación de dirección","El público elige el juego que debe dirigir"]'::jsonb, null, 'Keith Johnstone — Loose Moose Theatre, Calgary', '⚠️ Marca rexistrada. Require permiso do International Theatresports Institute (impro.global). Dereitos de produción: 3% da recadación bruta. Existe acordo educativo para centros de ensino.', 'improvencyclopedia.org', true, 146, null),
  ('148', 'Formato: Theatresports', 'formato', 60, 'grupo', 'Formato competitivo por equipos creado por Keith Johnstone, con jueces y retos entre equipos.', '["Dividir en dos equipos y nombrar a un presentador","Los equipos se retan a juegos concretos","Un jurado puntúa cada intervención","Se penalizan los bloqueos y el humor fácil","Gana el equipo con más puntos al final del encuentro"]'::jsonb, 'Trabajo de equipo, variedad de juegos, relación con el público', '["Con público como jurado","Retos propuestos por el público"]'::jsonb, null, 'Keith Johnstone — primeira función oficial no Pumphouse Theatre, Calgary, 1977', '⚠️ Marca rexistrada. Require permiso do International Theatresports Institute (impro.global). Dereitos de produción: 3% da recadación bruta. Existe acordo educativo para centros de ensino.', 'improvencyclopedia.org', true, 147, null),
  ('149', 'Formato: Línea de tiempo', 'formato', 30, 'grupo', 'Una misma historia contada saltando adelante y atrás en el tiempo.', '["Marcar en el suelo una línea imaginaria: pasado a un lado, futuro al otro","Empezar por una escena en el centro de la línea","Los actores se desplazan para indicar el salto temporal","Cada escena nueva ilumina la anterior","Cerrar en el punto más antiguo o más lejano de la línea"]'::jsonb, 'Estructura no lineal, causa y consecuencia', '["Solo saltos hacia atrás","El público señala el punto de la línea"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 148, null),
  ('150', 'Formato: Invocación', 'formato', 10, 'grupo', 'Apertura de long form en la que el grupo explora una palabra desde cuatro ángulos antes de las escenas.', '["Tomar una palabra del público","Primera vuelta: qué es literalmente esa palabra","Segunda vuelta: hablarle a la palabra en segunda persona","Tercera vuelta: ser la palabra en primera persona","Cuarta vuelta: encarnarla físicamente, sin texto"]'::jsonb, 'Material común, tono de grupo, arranque de long form', '["Solo dos de las cuatro vueltas","Cerrar con una imagen coral"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 149, null),
  ('151', 'Formato: Seis episodios', 'formato', 35, 'grupo', 'Seis escenas cortas de la misma historia, tituladas de antemano por el público.', '["Pedir al público seis títulos de episodio","Escribirlos en orden y anunciarlos antes de cada escena","Cada escena debe justificar su título","Los personajes se mantienen entre episodios","El sexto episodio cierra la historia"]'::jsonb, 'Estructura impuesta, coherencia de personajes', '["Jugar los episodios en desorden","Solo cuatro episodios"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 150, null),
  ('152', 'Big Booty', 'calentamiento', 8, 'grupo', 'Juego de ritmo y números en círculo donde el error te manda al último puesto.', '["Círculo, cada persona recibe un número; el uno es ''Big Booty''","Marcar un ritmo constante con palmas o pies","Big Booty arranca: ''Big Booty, Big Booty, número tres''","El tres responde nombrándose y pasando a otro número","Quien falle el ritmo o el número pasa al último puesto y todos rotan"]'::jsonb, 'Atención, ritmo, aceptar el error con humor', '["Sin números, con nombres","Acelerar el ritmo cada minuto"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 151, null),
  ('153', 'Whoosh', 'calentamiento', 8, 'grupo', 'Energía que circula por el círculo y se transforma con órdenes de sonido y gesto.', '["Círculo de pie","Pasar la energía al de al lado diciendo ''whoosh'' con un gesto de empuje","''Whoa'' con las manos por delante devuelve la energía en sentido contrario","''Zap'' la lanza en cruz a cualquiera del círculo","Añadir órdenes nuevas cuando el grupo domine las tres"]'::jsonb, 'Energía, atención periférica, coordinación', '["Añadir una orden inventada por el grupo","Sin palabras, solo gestos"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 152, null),
  ('154', 'Bippety Bop', 'calentamiento', 8, 'grupo', 'Alguien en el centro señala y ordena, y hay que responder antes de que termine de hablar.', '["Una persona en el centro del círculo","Señala a alguien y dice ''bippety bop'' antes de que responda ''bop''","Si solo dice ''bop'', el señalado debe callar","Quien se equivoque pasa al centro","Añadir figuras de grupo con los dos vecinos: elefante, palmera, tostadora"]'::jsonb, 'Reacción, presencia, colaboración con los vecinos', '["Solo figuras, sin bippety bop","Dos personas en el centro"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 153, null),
  ('155', 'Fruta en cesta', 'calentamiento', 8, 'grupo', 'Sillas en círculo y una persona sin sitio que lanza afirmaciones para hacer mover al grupo.', '["Sillas en círculo, una menos que el número de personas","Quien queda de pie dice ''que se levante todo el que...'' y completa con algo cierto","Todos los que cumplan esa condición cambian de silla","No vale sentarse en la silla de al lado","Quien se quede sin sitio lanza la siguiente"]'::jsonb, 'Energía, conocerse, riesgo controlado', '["Solo afirmaciones sobre improvisación","Sin sillas, marcando el sitio en el suelo"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 154, null),
  ('156', 'Nudo humano', 'calentamiento', 10, 'grupo', 'El grupo se enreda dándose las manos y tiene que deshacer el nudo sin soltarse.', '["Círculo cerrado y apretado","Cada persona da la mano derecha a alguien de enfrente","Después la izquierda a otra persona distinta","Sin soltarse nunca, deshacer el nudo hasta volver al círculo","Si es imposible, reconocerlo y empezar de nuevo"]'::jsonb, 'Contacto, cooperación, paciencia', '["En silencio total","Con un solo portavoz que dirige"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 155, null),
  ('157', 'Samurái', 'calentamiento', 8, 'grupo', 'Golpes de katana imaginaria que circulan por el círculo con sonido y compromiso físico.', '["Círculo, todos con la katana imaginaria en alto","Alguien lanza un golpe hacia otra persona con un grito","Los dos vecinos de esa persona atacan a la vez con otro grito","La persona atacada lanza el siguiente golpe","Quien tarde o dude sale del círculo"]'::jsonb, 'Compromiso físico, atención, energía de grupo', '["Sin eliminación","Añadir un golpe que rebota"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 156, null),
  ('158', 'Alien, tigre, vaca', 'calentamiento', 6, 'grupo', 'Piedra, papel o tijera de cuerpo entero jugado por todo el grupo a la vez.', '["Acordar el gesto y el sonido de alien, tigre y vaca","Dividir el grupo en dos mitades enfrentadas","Cada mitad decide en secreto cuál de los tres va a hacer","A la de tres, ambas mitades lo hacen a la vez","Alien gana a vaca, vaca a tigre, tigre a alien"]'::jsonb, 'Decisión colectiva rápida, compromiso, ridículo compartido', '["Por parejas en vez de por mitades","Inventar tres criaturas nuevas"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 157, null),
  ('159', 'Círculo de sonidos', 'calentamiento', 8, 'grupo', 'Un sonido con gesto circula por el grupo transformándose en cada persona.', '["Círculo de pie","Alguien lanza un sonido con un gesto asociado","El siguiente lo recibe imitándolo exactamente","Después lo transforma en otro sonido y gesto propios","Continuar hasta dar la vuelta completa"]'::jsonb, 'Escucha, imitación precisa, transformación', '["Cruzando el círculo en vez de en orden","Sin gesto, solo voz"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 158, null),
  ('160', 'Ola de nombres', 'calentamiento', 6, 'grupo', 'Los nombres del grupo se convierten en una ola de movimiento y sonido.', '["Círculo de pie","Cada persona dice su nombre con un movimiento grande","El grupo entero repite nombre y movimiento a la vez","Continuar por todo el círculo","Segunda vuelta encadenando sin pausa"]'::jsonb, 'Aprender nombres, romper el pudor, energía inicial', '["Cada nombre con una emoción distinta","Solo con la primera sílaba del nombre"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 159, null),
  ('161', 'Hipnosis colombiana', 'calentamiento', 10, 'parejas', 'Ejercicio de Augusto Boal: una mano guía la cara del compañero por el espacio.', '["Por parejas, A coloca su mano a un palmo de la cara de B","B mantiene siempre esa distancia exacta, como hipnotizado","A mueve la mano lentamente por el espacio: arriba, abajo, en giro","B sigue con todo el cuerpo, no solo con la cabeza","Cambiar de rol y después probar con las dos manos y cuatro personas"]'::jsonb, 'Liderazgo, escucha física, conciencia del poder', '["Cadenas de cuatro personas","Sin manos, guiando con la mirada"]'::jsonb, null, 'Augusto Boal — Teatro do Oprimido', null, 'improvencyclopedia.org', true, 160, null),
  ('162', 'Punto caliente', 'calentamiento', 10, 'grupo', 'Alguien canta en el centro y es relevado en cuanto otro tiene una canción que se le parezca.', '["Círculo con una persona en el centro","Empieza a cantar cualquier canción que sepa","En cuanto a alguien le venga otra canción asociada, entra y la releva","El relevo debe ser inmediato, sin dejar silencio","Nadie debe quedarse solo en el centro mucho tiempo"]'::jsonb, 'Asociación, apoyo al compañero, pérdida del miedo a cantar', '["Solo canciones en gallego o en castellano","Con textos hablados en vez de canciones"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 161, null),
  ('163', '¿Qué estás haciendo?', 'calentamiento', 8, 'grupo', 'Cada uno hace una acción distinta de la que acaba de anunciar en voz alta.', '["Dos filas enfrentadas o un círculo","A empieza a mimar una acción cualquiera","B pregunta ''¿qué estás haciendo?''","A responde con una acción completamente distinta de la que hace","B empieza a mimar esa acción nombrada y le toca a otro preguntar"]'::jsonb, 'Disociar cuerpo y palabra, agilidad, romper el automatismo', '["Encadenar sin pausa","Prohibido repetir verbos"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 162, null),
  ('164', 'Espina dorsal del cuento', 'entrenamiento', 12, 'grupo', 'Estructura narrativa de Kenn Adams con ocho conectores fijos para construir una historia completa.', '["Escribir o recordar la secuencia: érase una vez / todos los días / hasta que un día / por eso / por eso / por eso / hasta que finalmente / y desde entonces","En círculo, cada persona aporta una frase siguiendo el orden","No se puede saltar ni repetir conector","Al llegar al final, comprobar si la historia se sostiene","Repetir con otra historia más rápido"]'::jsonb, 'Estructura narrativa, causa y efecto, finales que cierran', '["Aplicarla directamente a una escena","Dos historias entrelazadas con la misma espina"]'::jsonb, null, 'Kenn Adams', null, 'improvencyclopedia.org', true, 163, null),
  ('165', 'Sí, hagámoslo', 'entrenamiento', 8, 'grupo', 'Todo lo que alguien propone se acepta con entusiasmo y se hace de inmediato.', '["El grupo camina por el espacio","Alguien propone en voz alta: ''vamos a remar''","Todos responden ''¡sí, hagámoslo!'' y lo hacen de verdad","Al poco, otra persona propone algo distinto","Nadie puede rechazar ni matizar una propuesta"]'::jsonb, 'Aceptación total, entusiasmo, grupo por encima del individuo', '["Versión contraria: rechazarlo todo, para notar la diferencia","Solo propuestas absurdas"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 164, null),
  ('166', 'Escena de tres frases', 'entrenamiento', 10, 'parejas', 'Una escena completa que solo puede durar tres réplicas.', '["Dos actores en escena","Solo se pueden decir tres frases en total","La primera establece quiénes son y dónde están","La segunda introduce el conflicto","La tercera lo resuelve o lo revienta"]'::jsonb, 'Economía, precisión, información en la primera frase', '["Una sola frase","Cinco frases con un giro obligatorio en la cuarta"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 165, null),
  ('167', 'Grommelot', 'entrenamiento', 10, 'parejas', 'Escena completa en un idioma inventado, donde todo el sentido lo lleva el cuerpo y la entonación.', '["Escoger una situación con una intención clara","Jugar la escena en un idioma inventado, sin palabras reales","Mantener la entonación, el ritmo y el gesto de una conversación normal","No caer en sonidos aleatorios: hay que querer decir algo","Comentar después si el público entendió la situación"]'::jsonb, 'Intención por encima del texto, expresividad corporal', '["Un idioma inventado distinto por personaje","Mezclar grommelot y lengua real"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 166, null),
  ('168', 'Traducir el idioma inventado', 'entrenamiento', 12, 'grupo', 'Un actor habla en idioma inventado y otro traduce sus palabras al público.', '["Un actor es el experto extranjero, otro su intérprete","El experto responde a preguntas en idioma inventado","El intérprete traduce, alargando o acortando a su gusto","El experto debe aceptar todo lo que el intérprete le atribuye","Cambiar de roles a mitad de juego"]'::jsonb, 'Aceptación, escucha, comicidad del desajuste', '["Dos intérpretes que se contradicen","El público hace las preguntas"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 167, null),
  ('169', 'Dotaciones', 'entrenamiento', 12, 'grupo', 'Un actor sale de la sala y vuelve sin saber quién es: los demás se lo hacen descubrir.', '["Un actor sale fuera","El resto acuerda quién es, dónde está y qué le pasa","El actor vuelve y empieza la escena sin saber nada","Los demás le dan pistas sin decírselo nunca directamente","La escena acaba cuando él lo verbaliza"]'::jsonb, 'Dar información sin bloquear, escucha, paciencia', '["Dotar solo la profesión","Dos actores dotados a la vez"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 168, null),
  ('170', 'Salto en el espacio', 'entrenamiento', 12, 'grupo', 'Las escenas se apilan hacia arriba y después se van deshaciendo en orden inverso.', '["Un actor empieza una escena solo","Entra un segundo y arranca una escena nueva desde la posición congelada del primero","Repetir hasta tener cuatro o cinco escenas apiladas","Al llegar al tope, los actores van saliendo en orden inverso","Cada escena que reaparece continúa exactamente donde se quedó"]'::jsonb, 'Memoria de escena, transición, resistencia', '["Solo tres niveles","Los que salen deben recordar la primera frase exacta"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 169, null),
  ('171', 'Dar y tomar', 'entrenamiento', 10, 'grupo', 'Solo se puede mover o hablar una persona a la vez: el foco se cede y se toma.', '["Cuatro o cinco actores en el espacio","Solo uno puede moverse o hablar en cada momento","Los demás quedan absolutamente quietos","El que tiene el foco decide cuándo cederlo","Nadie debe robarlo ni quedárselo demasiado"]'::jsonb, 'Conciencia del foco, generosidad, disciplina de grupo', '["Con texto de una escena real","Cambios cada vez más rápidos"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 170, null),
  ('172', 'Pintar la escena', 'entrenamiento', 12, 'grupo', 'Antes de actuar, el grupo describe en voz alta el espacio hasta que todos lo ven igual.', '["Recoger un lugar del público","Por turnos, cada persona añade un detalle concreto del espacio","No se puede contradecir lo que ya se ha dicho","Cuando el espacio esté claro, empezar la escena dentro de él","Respetar todos los objetos y distancias que se nombraron"]'::jsonb, 'Espacio compartido, objeto imaginario, memoria común', '["Detalles solo de un sentido: olores, sonidos","Pintar el espacio con el cuerpo, sin hablar"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 171, null),
  ('173', 'Última frase', 'entrenamiento', 10, 'parejas', 'La escena debe terminar exactamente con una frase dada de antemano.', '["El público propone una frase cualquiera","Los actores no saben de qué va la escena","Deben improvisar hasta que esa frase encaje como última réplica","La frase tiene que sonar inevitable, no forzada","Repetir con la misma frase y otra escena distinta"]'::jsonb, 'Estructura, dirección hacia un final, justificación', '["Frase obligatoria al principio y al final","Dos frases: una para cada actor"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 172, null),
  ('174', 'Sentado, de pie, tumbado', 'entrenamiento', 12, 'grupo', 'Tres actores que deben mantener siempre las tres posturas repartidas entre ellos.', '["Tres actores en escena","En todo momento uno está sentado, otro de pie y otro tumbado","Si alguien cambia de postura, los otros deben reajustarse enseguida","Justificar siempre el cambio dentro de la escena","No parar la escena para recolocarse"]'::jsonb, 'Atención periférica, justificación, escena bajo restricción', '["Cuatro posturas con cuatro actores","Cambiar de postura cada vez que alguien haga una pregunta"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 173, null),
  ('175', 'Pantalla partida', 'entrenamiento', 12, 'grupo', 'Dos escenas simultáneas en mitades del escenario que se van contagiando.', '["Dividir el escenario en dos mitades visibles","Una pareja en cada mitad, con escenas distintas","Solo suena la mitad que señala el facilitador","Al cambiar el foco, la otra escena sigue en mudo","Buscar que las dos escenas acaben rimando"]'::jsonb, 'Foco compartido, resonancia entre escenas', '["Tres mitades","Las dos escenas se oyen a la vez al final"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 174, null),
  ('176', 'Manías en la fiesta', 'juego', 15, 'grupo', 'Un anfitrión recibe invitados con rarezas secretas que tiene que adivinar.', '["Un actor es el anfitrión y sale de la sala","El público propone una manía para cada invitado","Los invitados van llegando de uno en uno y juegan su rareza sin nombrarla","El anfitrión reacciona con normalidad y va aventurando quién es cada uno","Adivinar la última al final de la fiesta"]'::jsonb, 'Personaje físico, dar pistas sin explicar', '["Manías relacionadas entre sí","El anfitrión también tiene una rareza"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 175, null),
  ('177', 'El peor del mundo', 'juego', 10, 'grupo', 'Serie de intervenciones brevísimas mostrando la peor versión posible de algo.', '["El público propone una categoría: el peor camarero, el peor profesor","Los actores en fila","Uno da un paso al frente y hace una intervención de tres segundos","Vuelve a la fila y sale otro inmediatamente","Cambiar de categoría cuando decaiga"]'::jsonb, 'Remate rápido, atrevimiento, ritmo', '["Encadenar sin silencio","Por parejas: el peor y el mejor"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 176, null),
  ('178', 'Rueda de prensa', 'juego', 15, 'grupo', 'Un personaje comparece ante la prensa sin saber quién es ni por qué está allí.', '["Un actor sale de la sala","El público decide quién es y qué escándalo protagoniza","El actor vuelve y se sienta ante los periodistas","Los periodistas preguntan sin desvelar la identidad","La rueda acaba cuando el compareciente lo dice en voz alta"]'::jsonb, 'Dotación, escucha, construcción bajo presión', '["Con el público haciendo de prensa","Dos comparecientes contradictorios"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 177, null),
  ('179', 'Efectos de sonido', 'juego', 12, 'grupo', 'Dos actores juegan la escena y otros dos hacen todos los sonidos con la boca.', '["Dos actores en escena, dos a los lados como efectistas","Cualquier acción debe sonar: puertas, pasos, lluvia, motores","Los actores deben aceptar el sonido aunque no sea el que esperaban","Los efectistas pueden sabotear con sonidos inesperados","Cerrar con un efecto sonoro grande"]'::jsonb, 'Aceptación, escucha, comicidad del desajuste', '["Con público voluntario como efectista","Los efectos los hace el propio actor"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 178, null),
  ('180', 'Autoestopista', 'juego', 15, 'grupo', 'En un coche imaginario, cada nuevo pasajero contagia su manera de ser a todos.', '["Cuatro sillas en formación de coche, un actor conduciendo","Aparece un autoestopista con una característica muy marcada","Al subir, todos los del coche adoptan esa característica","Rotan las posiciones: el conductor sale y todos se desplazan","Repetir con un autoestopista nuevo"]'::jsonb, 'Contagio, personaje físico, transición limpia', '["Con emociones en vez de manías","El público propone cada autoestopista"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 179, null),
  ('181', 'La máquina de escribir', 'juego', 15, 'grupo', 'Un narrador escribe una novela en voz alta y los actores representan lo que dicta.', '["Un actor se sienta aparte con una máquina de escribir imaginaria","El público propone género y título de la novela","El narrador va escribiendo en voz alta","Los actores representan cada frase según se dicta, incluidos los adverbios","El narrador puede tachar y reescribir, y los actores rehacen la acción"]'::jsonb, 'Narración, obediencia escénica, reincorporación', '["Los actores pueden proponer y el narrador acepta","Dos narradores que compiten por la novela"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 180, null),
  ('182', 'Trilogía del error', 'formato', 70, 'grupo', 'Long form cuya estructura se basa en el juego de posibilidades que el azar provoca en el desarrollo de una historia lineal: la historia se interrumpe progresivamente con acontecimientos incidentales que construyen tres historias paralelas a partir de una misma escena inicial.', '["Ficha descriptiva, no guía de montaje","Duración: 70 minutos. Elenco en gira: 5 personas","Escena inicial única que funciona como génesis de todo el espectáculo","Interrupciones incidentales que bifurcan la historia lineal","Tres líneas paralelas derivadas del mismo arranque"]'::jsonb, 'Referencia de formato: azar como motor estructural y bifurcación narrativa', '["Ver el vídeo del espectáculo en el canal de Improvisual Project"]'::jsonb, null, 'Dramaturgia: David Moncada. Dirección: Gigio Giraldo. Elenco: David Moncada, Álvaro Lozano, Víctor Tarazona, Felipe Correa. Producción: María Paula Franky. Improvisual Project (Bogotá, Colombia), estreado en 2013 no festival «Mendoza te improvisa»', '⚠️ Obra de autoría. Non é un exercicio de dominio público. Para montala, contactar con Improvisual Project: contacto@improvisualproject.com', 'improvisualproject.com/trilogia-del-error', true, 181, null),
  ('183', 'Conejo conejo', 'calentamiento', 6, 'grupo', 'Un conejo imaginario formado con las manos salta de persona a persona por el círculo.', '["Círculo de pie","Una persona hace el conejo con las manos sobre su cabeza y dice ''conejo, conejo''","Sus dos vecinos hacen las orejas a los lados","El del centro lanza el conejo a otra persona del círculo","Los vecinos de esa nueva persona deben reaccionar al instante"]'::jsonb, 'Atención periférica, reflejos, colaboración con los vecinos', '["Acelerar progresivamente","Añadir un segundo conejo simultáneo"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 182, null),
  ('184', 'La masa', 'calentamiento', 6, 'grupo', 'El grupo se mueve como un solo organismo, sin líder designado.', '["Todos muy juntos, en bloque compacto","El grupo empieza a desplazarse por la sala","No hay líder: cualquiera puede iniciar un cambio de dirección","Nadie puede quedarse descolgado del bloque","Probar a cambiar de velocidad y de altura sin hablar"]'::jsonb, 'Escucha de grupo, liderazgo compartido, cohesión física', '["Añadir sonido colectivo","La masa debe atravesar obstáculos imaginarios"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 183, null),
  ('185', 'Cruzar el círculo', 'calentamiento', 8, 'grupo', 'Se cruza el círculo pidiendo permiso con la mirada y el nombre de quien ocupa el sitio.', '["Círculo amplio de pie","A dice el nombre de B y espera su gesto de permiso","Cuando B asiente, A camina hacia el sitio de B","B debe salir antes de que A llegue, buscando ya el nombre de C","Encadenar sin que el círculo se rompa"]'::jsonb, 'Nombres, contacto visual, anticipación', '["Dos cruces simultáneos","Sin nombres, solo con la mirada"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 184, null),
  ('186', 'Volea de nombres', 'calentamiento', 6, 'grupo', 'Una pelota imaginaria vuela por el círculo y siempre se anuncia el nombre de quien la recibe.', '["Círculo de pie","Lanzar una pelota imaginaria diciendo el nombre de quien la recibe","Quien la recibe debe atraparla de verdad, con el cuerpo","Ir añadiendo más pelotas al mismo tiempo","Si una pelota se cae, reconocerlo y seguir"]'::jsonb, 'Nombres, foco compartido, atención múltiple', '["Pelotas de distinto peso y tamaño","Añadir una pelota que quema"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 185, null),
  ('187', 'Palma que pasa', 'calentamiento', 6, 'grupo', 'Una palmada circula por el grupo buscando la sincronía perfecta entre quien la da y quien la recibe.', '["Círculo de pie","La palmada se pasa al vecino intentando que las dos manos suenen a la vez","Buscar que suene como una sola palmada, no como dos","Cuando el grupo lo domine, permitir cambios de sentido","Acelerar hasta el límite del grupo"]'::jsonb, 'Sincronía, contacto visual, escucha', '["Cruzando el círculo","Con los ojos cerrados"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 186, null),
  ('188', 'Contar hasta veinte', 'calentamiento', 8, 'grupo', 'El grupo cuenta hasta veinte sin orden previo y sin que dos personas hablen a la vez.', '["El grupo en círculo o disperso, con los ojos cerrados","Alguien dice ''uno'' cuando lo sienta","Otro dice ''dos'', y así sucesivamente","Si dos personas hablan a la vez, se vuelve a empezar desde uno","No vale pactar turnos ni seguir un orden"]'::jsonb, 'Escucha colectiva, aceptar el fracaso, paciencia', '["Contar hacia atrás","Con los ojos abiertos, más difícil de lo que parece"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 187, null),
  ('189', 'Andar por números', 'calentamiento', 8, 'grupo', 'Cinco velocidades de desplazamiento por la sala que el facilitador va cantando.', '["Caminar por el espacio ocupando los huecos","Uno es a cámara lentísima; cinco es correr al límite","El facilitador canta un número y todos cambian al instante","Trabajar sobre todo el uno y el cinco, que son los que cuestan","Después añadir emoción a cada velocidad"]'::jsonb, 'Conciencia del espacio, control del ritmo, disponibilidad física', '["Con estados de ánimo en vez de velocidades","Cada uno elige su número y lo mantiene"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 188, null),
  ('190', 'Sí, y... en círculo', 'calentamiento', 8, 'grupo', 'Planificación colectiva de un evento imposible donde todo se acepta y se amplía.', '["Círculo de pie","Alguien propone: ''vamos a organizar una fiesta''","El siguiente dice ''sí, y...'' añadiendo un detalle","Nadie puede corregir ni matizar lo anterior","Dar dos vueltas completas y ver en qué acabó la fiesta"]'::jsonb, 'Aceptación, construcción acumulativa, entusiasmo', '["Versión ''sí, pero...'' para notar el contraste","Planificar algo imposible: una boda en Marte"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 189, null),
  ('191', 'Gritos primarios', 'calentamiento', 5, 'grupo', 'Descarga vocal colectiva para soltar la voz y el cuerpo antes de empezar.', '["Todos de pie, separados","Empezar con un sonido muy grave desde el suelo","Ir subiendo el cuerpo y el tono a la vez","Terminar con un grito colectivo con los brazos arriba","Soltar y quedarse en silencio unos segundos"]'::jsonb, 'Soltar la voz, romper el pudor, nivelar la energía', '["En dos grupos que se responden","Con una emoción concreta cada vez"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 190, null),
  ('192', 'Rituales', 'calentamiento', 10, 'grupo', 'El grupo inventa un ritual colectivo repitiendo y ampliando gestos sin hablar.', '["Alguien empieza un gesto repetitivo con sonido","El grupo lo copia exactamente","Cuando esté asentado, otra persona lo transforma","Todos adoptan la transformación","Continuar hasta que el ritual tenga tres o cuatro fases"]'::jsonb, 'Unísono, transformación colectiva, trabajo coral', '["Sin sonido","Dos rituales enfrentados que se contagian"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 191, null),
  ('193', 'Trabalenguas en cadena', 'calentamiento', 6, 'grupo', 'Un trabalenguas circula por el grupo acelerando hasta que alguien lo rompe.', '["Elegir un trabalenguas corto que todos conozcan","Decirlo por turnos, uno cada persona","Cada vuelta se hace más rápido","Quien lo rompa propone el siguiente trabalenguas","Terminar con todos diciéndolo a la vez"]'::jsonb, 'Dicción, articulación, aceptar el error en público', '["En gallego y en castellano alternando","Cantado en vez de hablado"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 192, null),
  ('194', 'Presentación aliterada', 'calentamiento', 8, 'grupo', 'Cada persona se presenta con un adjetivo y una acción que empiecen por su inicial.', '["Círculo de pie","Cada persona dice su nombre con un adjetivo de su misma letra","Añade un gesto que también encaje","El grupo repite nombre, adjetivo y gesto","Segunda vuelta intentando recordar los de todos"]'::jsonb, 'Nombres, agilidad verbal, memoria de grupo', '["Acumulativo: repetir todos los anteriores","Con la letra final del nombre"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 193, null),
  ('195', 'Bumpity bump', 'calentamiento', 8, 'grupo', 'Hay que decir el nombre del vecino antes de que quien está en el centro termine la fórmula.', '["Círculo con una persona en el centro","Señala a alguien y dice ''izquierda, bumpity bump bump bump''","El señalado debe decir el nombre de su vecino izquierdo antes de que acabe","Si falla, pasa al centro","Alternar ''izquierda'' y ''derecha'' sin avisar"]'::jsonb, 'Nombres bajo presión, reflejos', '["Añadir ''loop'' para que todo el círculo rote","Con el nombre de dos vecinos"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 194, null),
  ('196', 'Palomitas', 'calentamiento', 5, 'grupo', 'El grupo salta como palomitas evitando saltar a la vez que otro.', '["Todos agachados por el espacio","Cualquiera puede saltar en cualquier momento con un sonido","Si dos saltan a la vez, ambos vuelven abajo","Intentar llegar a diez saltos limpios seguidos","No mirarse ni pactar el orden"]'::jsonb, 'Escucha colectiva, impulso, aceptar el choque', '["Añadir palabra al saltar","Contar hasta veinte saltando"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 195, null),
  ('197', 'Energía del uno al diez', 'calentamiento', 8, 'parejas', 'Una escena breve se repite subiendo la energía de nivel en nivel.', '["Elegir una situación cotidiana muy simple","Jugarla en nivel uno: energía mínima, casi inmóvil","Repetirla en nivel cinco","Repetirla en nivel diez, al máximo","Volver al cinco y notar la diferencia"]'::jsonb, 'Control del volumen escénico, rango de intensidad', '["Cada actor en un nivel distinto","El facilitador canta el nivel en mitad de la escena"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 196, null),
  ('198', 'Zombi', 'calentamiento', 8, 'grupo', 'Un zombi avanza lentamente hacia alguien que solo puede salvarse diciendo el nombre de otro.', '["El grupo disperso, uno hace de zombi","El zombi avanza muy despacio hacia una persona","Esa persona solo se salva diciendo el nombre de otra antes de ser tocada","El zombi cambia entonces de objetivo","Si toca a alguien, ese pasa a ser el zombi"]'::jsonb, 'Nombres, tensión, atención constante', '["Dos zombis","El nombre debe ir acompañado de contacto visual"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 197, null),
  ('199', 'Un pato', 'calentamiento', 6, 'grupo', 'Frase acumulativa que crece con cada vuelta y hay que decir entera y sin errores.', '["Círculo de pie","El primero dice: ''un pato''","El segundo: ''un pato, dos patas''","El tercero añade ''pluf'' y así sigue creciendo la fórmula","Quien se equivoque reinicia la cuenta"]'::jsonb, 'Memoria, ritmo, aceptar el error', '["Acelerar cada vuelta","Añadir un gesto por elemento"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 198, null),
  ('200', 'Qué ha cambiado', 'calentamiento', 8, 'parejas', 'Por parejas, observarse y detectar los cambios que el otro ha hecho de espaldas.', '["Por parejas, mirarse en detalle durante treinta segundos","Darse la espalda y cambiar tres cosas del aspecto propio","Volver a mirarse y adivinar qué cambió","Repetir subiendo a cinco cambios","Comentar qué se ve y qué no se ve"]'::jsonb, 'Observación, presencia, detalle', '["En grupo, con una sola persona cambiando","Cambios en la actitud, no en el aspecto"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 199, null),
  ('201', 'Quién, dónde, qué', 'entrenamiento', 12, 'parejas', 'Establecer relación, lugar y actividad en las tres primeras réplicas de la escena.', '["Dos actores empiezan sin ninguna sugerencia","La primera frase establece quiénes son el uno para el otro","La segunda establece dónde están","La tercera establece qué están haciendo","A partir de ahí, la escena sigue libremente"]'::jsonb, 'Información temprana, evitar escenas flotantes', '["En orden inverso: primero la actividad","Sin nombrar nada explícitamente, solo sugiriéndolo"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 200, null),
  ('202', 'Solo preguntas', 'entrenamiento', 10, 'parejas', 'Escena en la que todas las réplicas tienen que ser preguntas.', '["Dos actores en escena","Todo lo que se diga debe ser una pregunta","No vale repetir la pregunta del otro ni decir ''qué''","Quien afirme, dude demasiado o repita, sale y entra otro","Mantener a pesar de todo una situación reconocible"]'::jsonb, 'Agilidad, presión escénica, escucha', '["Prohibido preguntar: solo afirmaciones","Alternando pregunta y afirmación"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 201, null),
  ('203', 'Última letra', 'entrenamiento', 10, 'parejas', 'Cada réplica debe empezar por la letra en la que terminó la anterior.', '["Dos actores en escena","La primera frase es libre","La siguiente empieza por la última letra de la frase anterior","Mantener la escena viva, no convertirlo en un ejercicio de vocabulario","Si alguien falla, se corrige y se sigue"]'::jsonb, 'Doble atención, no abandonar la escena bajo restricción', '["Por orden alfabético en vez de última letra","Prohibida una letra concreta"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 202, null),
  ('204', 'Experto de dos cabezas', 'entrenamiento', 12, 'grupo', 'Dos actores forman un único experto que responde una palabra cada uno.', '["Dos actores hombro con hombro forman un solo personaje","El público pregunta sobre un tema","Responden construyendo las frases palabra a palabra, alternando","Ninguno puede planificar hacia dónde va la frase","Terminar cuando la respuesta se cierre sola"]'::jsonb, 'Cesión del control, escucha extrema, aceptación', '["Tres cabezas","Con un moderador que reformula las preguntas"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 203, null),
  ('205', 'Cuadrantes emocionales', 'entrenamiento', 15, 'grupo', 'El escenario se divide en cuatro zonas, cada una con una emoción distinta.', '["Marcar cuatro cuadrantes en el suelo y asignar una emoción a cada uno","Los actores juegan una escena moviéndose por el espacio","Al pisar un cuadrante, adoptan esa emoción de inmediato","La escena y el texto continúan sin cortarse","Justificar el cambio emocional dentro de la ficción"]'::jsonb, 'Cambio emocional inmediato, uso del espacio', '["Emociones propuestas por el público","Los cuadrantes cambian de emoción a mitad"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 204, null),
  ('206', 'Paseo de personaje', 'entrenamiento', 15, 'grupo', 'Construcción de personaje desde un solo punto del cuerpo que lidera el movimiento.', '["Caminar por la sala con normalidad","El facilitador nombra una parte del cuerpo que lidera: nariz, pecho, rodillas","Dejar que esa parte tire del resto del cuerpo","Cuando el andar esté claro, añadir voz y saludo","Cruzarse con otros personajes y presentarse"]'::jsonb, 'Personaje físico, evitar el personaje solo verbal', '["Cambiar de parte líder sin parar de andar","Reducir la exageración al veinte por ciento"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 205, null),
  ('207', 'Orden jerárquico', 'entrenamiento', 15, 'grupo', 'Cada actor recibe un número de estatus en secreto y el grupo debe ordenarse jugando.', '["Repartir números del uno al cinco en secreto","Jugar una escena de grupo en un lugar concreto","Cada actor comporta su estatus sin nombrarlo nunca","A mitad de escena, colocarse en fila según lo que se percibe","Comprobar los números reales"]'::jsonb, 'Estatus, lectura del comportamiento ajeno', '["Estatus que cambia a mitad de escena","Los actores no ven su propio número"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 206, null),
  ('208', 'Amo y criado', 'entrenamiento', 15, 'parejas', 'Pareja de estatus extremo donde el desastre va creciendo mientras se mantiene la jerarquía.', '["Uno es el amo y el otro el criado, con estatus muy marcados","El criado comete un pequeño error","Ninguno de los dos puede romper la jerarquía","Los errores van escalando hasta el desastre total","Mantener las formas hasta el último segundo"]'::jsonb, 'Estatus sostenido, escalada, comedia de contención', '["Invertir los estatus al final","Con tres criados"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 207, null),
  ('209', 'Hacer más interesante', 'entrenamiento', 12, 'parejas', 'El facilitador interrumpe pidiendo avanzar o profundizar según lo que necesite la escena.', '["Escena en curso entre dos actores","El facilitador dice ''avanza'' cuando la escena se estanca","Dice ''profundiza'' cuando pasa de puntillas sobre algo interesante","Los actores obedecen sin cortar la escena","Comentar después dónde estaba el material"]'::jsonb, 'Distinguir avanzar de profundizar, criterio dramático', '["Los propios actores piden avanzar o profundizar","El público decide"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 208, null),
  ('210', 'Salir por un motivo', 'entrenamiento', 12, 'grupo', 'Nadie puede abandonar la escena sin una razón justificada dentro de la ficción.', '["Escena de grupo en un lugar concreto","Nadie puede salir sin dar un motivo verosímil","''Me voy'' a secas no vale","El motivo debe estar relacionado con lo que ha pasado","Quien salga mal justificado vuelve a entrar y lo repite"]'::jsonb, 'Justificación, evitar abandonar la escena por comodidad', '["Tampoco se puede entrar sin motivo","El motivo debe abrir una trama nueva"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 209, null),
  ('211', 'Sin dudar', 'entrenamiento', 10, 'parejas', 'Escena en la que cualquier titubeo se penaliza al instante.', '["Dos actores en escena","El facilitador atiende solo a las pausas y las dudas","Al primer ''eeeh'' o silencio de búsqueda, suena una señal","El actor que dudó sale y entra otro","El objetivo no es hablar rápido sino no bloquearse"]'::jsonb, 'Fluidez, confianza en la primera idea', '["Sin eliminación, solo señal sonora","Permitir un silencio si es intencionado y sostenido"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 210, null),
  ('212', 'Fila a ciegas', 'entrenamiento', 12, 'grupo', 'Un actor sale y vuelve a una fila de personajes que debe identificar por lo que le dicen.', '["Un actor sale de la sala","Los demás se colocan en fila y reciben una identidad del público","El actor vuelve y se acerca a cada uno","Cada personaje le habla dándole pistas sin decir quién es","El actor va adivinando de uno en uno"]'::jsonb, 'Dar información oblicua, escucha, deducción en escena', '["Identidades relacionadas entre sí","El actor debe adivinar también dónde están"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 211, null),
  ('213', 'Cuerpos completos', 'entrenamiento', 12, 'grupo', 'Entre varios actores se forma una sola criatura o máquina que se mueve coordinada.', '["Un actor entra y adopta una forma","Otro se une completando la figura, tocándolo","Seguir añadiendo hasta que la criatura esté completa","La criatura debe moverse y sonar como una unidad","Deshacerla en orden inverso"]'::jsonb, 'Contacto, imagen de grupo, coordinación', '["Con función concreta: una máquina que fabrica algo","La criatura interactúa con un actor externo"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 212, null),
  ('214', 'Escultores', 'entrenamiento', 12, 'parejas', 'Un actor moldea el cuerpo del otro como si fuera arcilla, sin hablar.', '["Por parejas, uno es escultor y otro arcilla","La arcilla se deja mover sin oponer resistencia ni ayudar","El escultor coloca cada parte del cuerpo con cuidado","Al terminar, la escultura cobra vida durante diez segundos","Cambiar de rol"]'::jsonb, 'Contacto, precisión física, confianza', '["Escultura de una emoción concreta","Galería: todas las esculturas expuestas a la vez"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 213, null),
  ('215', 'Objetivo y obstáculo', 'entrenamiento', 15, 'parejas', 'Cada actor entra con un deseo claro y con algo que se lo impide.', '["Cada actor decide en secreto qué quiere de la otra persona","Decide también qué le impide pedirlo directamente","Jugar la escena persiguiendo el objetivo sin nombrarlo","No abandonar el objetivo aunque la escena derive","Al final, revelar cuál era el objetivo de cada uno"]'::jsonb, 'Intención dramática, evitar escenas sin conflicto', '["Objetivos incompatibles entre los dos","El obstáculo lo pone el público"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 214, null),
  ('216', 'Opuestos', 'entrenamiento', 12, 'parejas', 'Dos personajes construidos como contrarios exactos en ritmo, estatus y energía.', '["Definir un eje: rápido y lento, alto y bajo estatus, cálido y frío","Cada actor se sitúa en un extremo del eje","Jugar una escena cotidiana manteniendo la polaridad","Ninguno puede acercarse al punto medio","Terminar cuando uno de los dos ceda, y verlo"]'::jsonb, 'Contraste, personajes diferenciados', '["Cambiar de eje sin parar la escena","Tres actores con tres posiciones del eje"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 215, null),
  ('217', 'Puertas', 'entrenamiento', 12, 'grupo', 'Cada entrada por una puerta imaginaria trae un personaje y un estado nuevos.', '["Marcar una puerta imaginaria en el espacio","Un actor entra por ella con un personaje claro","Juega una escena breve y sale","Vuelve a entrar como alguien completamente distinto","Cada entrada debe cambiar el ambiente de la escena"]'::jsonb, 'Entradas potentes, variedad de personaje', '["La puerta da a un sitio distinto cada vez","Dos puertas con reglas diferentes"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 216, null),
  ('218', 'Cinco cosas', 'entrenamiento', 8, 'grupo', 'Enumerar cinco elementos de una categoría sin pensar, con el grupo contando en voz alta.', '["Círculo de pie","Alguien pide a otro: ''cinco cosas que hay en una cocina''","El grupo cuenta en voz alta del uno al cinco marcando el ritmo","Hay que responder al ritmo, sin pararse a pensar","Al terminar, todos celebran y se pasa a otro"]'::jsonb, 'Perder el miedo al error, velocidad, celebración del fallo', '["Categorías imposibles","Diez cosas en vez de cinco"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 217, null),
  ('219', 'Tocar para hablar', 'entrenamiento', 12, 'parejas', 'Solo se puede hablar mientras se mantiene contacto físico con el compañero.', '["Dos actores en escena","Solo se puede hablar si hay contacto físico entre ambos","El contacto debe justificarse dentro de la escena","Al soltarse, la escena continúa en silencio","Buscar razones creíbles para volver a tocarse"]'::jsonb, 'Contacto justificado, relación física, escena sin texto', '["Al contrario: solo se habla sin contacto","En grupo, con contacto en cadena"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 218, null),
  ('220', 'Mover o hablar', 'entrenamiento', 12, 'parejas', 'No se puede hablar y moverse al mismo tiempo: hay que elegir.', '["Dos actores en escena","Si un actor se mueve, no puede hablar","Si habla, debe estar completamente quieto","Los cambios deben ser limpios, sin solaparse","Notar cómo cambia el peso de cada frase"]'::jsonb, 'Precisión, valor del silencio, conciencia del gesto', '["Solo uno de los dos con la restricción","Aplicarlo a una escena de mucha acción"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 219, null),
  ('221', 'Historia, historia, muerte', 'juego', 15, 'grupo', 'Un director señala quién narra la historia, y quien falle es eliminado con dramatismo.', '["Los actores en fila, un director delante","El director señala a alguien que empieza a contar una historia","Al señalar a otro, este continúa exactamente donde se quedó, hasta media palabra","Quien dude, repita o rompa la historia, muere en escena","Continuar hasta que quede uno"]'::jsonb, 'Escucha, continuidad narrativa, muertes espectaculares', '["Cantada en vez de hablada","Sin eliminación, solo penalización"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 220, null),
  ('222', 'Superhéroes', 'juego', 15, 'grupo', 'Un superhéroe llama a sus compañeros de poderes absurdos para resolver una crisis.', '["El público propone una crisis mundial","Un actor entra como superhéroe y anuncia el problema","Llama a un compañero dándole un nombre y un poder absurdo","El nuevo entra aceptando ese poder y llama a otro","Resolver la crisis usando todos los poderes"]'::jsonb, 'Aceptación de dotación, compromiso, escalada', '["Poderes cada vez más inútiles","El último debe resolverlo todo solo"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 221, null),
  ('223', 'La pesadilla del actor', 'juego', 15, 'grupo', 'Un actor tiene un guion en la mano y debe leer sus frases; los demás improvisan alrededor.', '["Dar a un actor un texto cualquiera: un manual, una novela, un prospecto","Los demás improvisan una escena con una situación clara","El del guion solo puede decir las frases que lee, en orden","Los demás justifican todo lo que sale de ese texto","Cortar cuando la escena encuentre su final"]'::jsonb, 'Justificación extrema, aceptación de material ajeno', '["Dos actores con guiones distintos","El público elige el texto"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 222, null),
  ('224', 'La cita a ciegas', 'juego', 15, 'grupo', 'Alguien elige pareja entre tres candidatos con identidades secretas dadas por el público.', '["Un actor hace de pretendiente y se sienta de espaldas","El público asigna una identidad secreta a cada uno de los tres candidatos","El pretendiente hace preguntas y ellos responden desde su identidad","Elige a uno y explica por qué","Se revelan las tres identidades"]'::jsonb, 'Personaje claro, dar pistas sin decirlo, humor de contraste', '["Candidatos con identidades relacionadas","El público hace las preguntas"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 223, null),
  ('225', 'Presentación con diapositivas', 'juego', 12, 'grupo', 'Un conferenciante comenta unas diapositivas que forman otros actores con el cuerpo.', '["El público propone el tema de la conferencia y el destino del viaje","Un actor presenta las diapositivas de sus vacaciones","Al decir ''siguiente'', los otros forman una imagen congelada","El conferenciante debe justificar la imagen que le han hecho","Cerrar con la diapositiva más difícil"]'::jsonb, 'Justificación, imagen de grupo, reacción rápida', '["Diapositivas cada vez más absurdas","Dos conferenciantes que se contradicen"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 224, null),
  ('226', 'Marionetas', 'juego', 12, 'grupo', 'Dos actores son movidos físicamente por otros dos, que no hablan.', '["Dos actores en escena hablan pero no se mueven por su cuenta","Otros dos actores los colocan y los mueven como marionetas","Los actores hablados justifican cada postura que les imponen","Los manipuladores no pueden hablar","Cambiar de rol a mitad de escena"]'::jsonb, 'Cesión del control físico, justificación, comedia', '["Con público voluntario como manipulador","Un solo manipulador para dos marionetas"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 225, null),
  ('227', 'El poeta y su traductor', 'juego', 12, 'parejas', 'Un poeta recita en idioma inventado y su traductor lo convierte en poema.', '["El público propone un tema para el poema","El poeta recita en idioma inventado, con gran emoción","Se detiene en fragmentos cortos","El traductor convierte cada fragmento en verso castellano","El poema debe tener sentido de principio a fin"]'::jsonb, 'Escucha, aceptación, ritmo poético', '["El traductor traduce cada vez menos fielmente","Dos traductores en desacuerdo"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 226, null),
  ('228', 'Película extranjera', 'juego', 15, 'grupo', 'Dos actores hablan en idioma inventado y otros dos los subtitulan en voz alta.', '["El público propone país y género de la película","Dos actores juegan la escena en un idioma inventado","Cada uno tiene su subtitulador a un lado","Los subtituladores traducen justo después de cada frase","Los actores deben aceptar lo que se les atribuye"]'::jsonb, 'Escucha bidireccional, aceptación, comicidad del desajuste', '["Subtítulos cada vez más largos que la frase original","Un solo subtitulador para los dos"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 227, null),
  ('229', 'Crítica de cine', 'juego', 12, 'grupo', 'Dos críticos comentan una película que el público no ha visto, y los actores la representan.', '["El público propone el título de una película inexistente","Dos críticos la comentan como si la conocieran bien","Al mencionar una escena, los actores la representan al instante","Los críticos deben aceptar lo que ven y seguir comentando","Cerrar con la valoración final"]'::jsonb, 'Reincorporación, doble nivel, escucha', '["Críticos con opiniones opuestas","Los actores contradicen lo que dicen los críticos"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 228, null),
  ('230', 'Telediario', 'juego', 15, 'grupo', 'Informativo improvisado con presentadores, corresponsales, deportes y meteorología.', '["Repartir los papeles: presentador, corresponsal, deportes, tiempo","El público propone tres titulares","El presentador da paso a cada sección","Cada sección desarrolla su titular en escena","Cerrar volviendo al titular de apertura"]'::jsonb, 'Formato reconocible, transiciones, trabajo de conjunto', '["Con conexiones en directo que fallan","Telediario de otro planeta o de otra época"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 229, null),
  ('231', 'El anuncio', 'juego', 12, 'grupo', 'El grupo crea el anuncio de un producto imposible aceptando y ampliando cada idea.', '["El público propone un producto absurdo","Los actores van proponiendo ideas para el anuncio","Cada propuesta se recibe con entusiasmo total y se amplía","Nadie puede rechazar ninguna idea","Terminar rodando el anuncio completo"]'::jsonb, 'Aceptación entusiasta, construcción colectiva', '["Anuncio de algo que nadie querría","Con eslogan cantado"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 230, null),
  ('232', 'Radio a ciegas', 'juego', 15, 'grupo', 'Una escena radiofónica con voces y efectos, donde el público cierra los ojos.', '["Pedir al público que cierre los ojos","Los actores crean una historia solo con voz y sonidos","Todo debe entenderse sin ver nada: pasos, puertas, distancias","Marcar los cambios de espacio con sonido","Al final, pedir al público que abra los ojos y describa lo que vio"]'::jsonb, 'Trabajo vocal, sonido narrativo, precisión', '["Con un locutor que enmarca la historia","Género de terror o de misterio"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 231, null),
  ('233', 'Asesinato en cadena', 'juego', 15, 'grupo', 'Varios actores salen y vuelven de uno en uno para recibir una historia que se va deformando.', '["Tres actores salen de la sala","El primero recibe una escena muda con crimen, arma y lugar","Vuelve el segundo y el primero se lo transmite sin hablar","El segundo se lo pasa al tercero, también en silencio","El tercero cuenta en voz alta lo que ha entendido"]'::jsonb, 'Comunicación no verbal, aceptar la deformación', '["Con cuatro eslabones","Permitir sonidos pero no palabras"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 232, null),
  ('234', 'El taller de reparaciones', 'juego', 12, 'grupo', 'Los clientes traen objetos o mascotas estropeados que el técnico debe diagnosticar.', '["Un actor es el técnico del taller","Los clientes entran con un objeto imaginario averiado","No pueden decir qué es: solo describir el síntoma","El técnico diagnostica y repara","El cliente confirma o corrige con la reacción"]'::jsonb, 'Objeto imaginario, dotación, escucha', '["Taller veterinario con animales imposibles","El técnico nunca ha visto ese objeto"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 233, null),
  ('235', 'Trabajo nuevo', 'juego', 12, 'parejas', 'Alguien empieza en un trabajo nuevo comportándose como en el anterior.', '["El público propone dos profesiones muy distintas","Un actor es el jefe del trabajo nuevo","El otro llega el primer día pero actúa según su antiguo oficio","El jefe intenta corregirlo sin conseguirlo","La escena acaba cuando lo despide o lo asciende"]'::jsonb, 'Personaje, contraste, compromiso con la premisa', '["El jefe también viene de otro oficio","Tres profesiones encadenadas"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 234, null),
  ('236', 'El funeral', 'juego', 15, 'grupo', 'Varios personajes despiden al difunto revelando sin querer su verdadera relación con él.', '["El público propone quién ha muerto y de qué","Los actores hacen cola para hablar ante el féretro","Cada discurso revela algo nuevo sobre el difunto","Nadie puede contradecir lo dicho antes: hay que ampliarlo","El último discurso lo cambia todo"]'::jsonb, 'Reincorporación, construcción de un personaje ausente', '["El difunto se levanta al final","Discursos cantados"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 235, null),
  ('237', 'Grandes éxitos', 'juego', 15, 'grupo', 'Teletienda que vende un recopilatorio de canciones sobre un tema propuesto.', '["El público propone un tema para el recopilatorio","Dos presentadores lo anuncian con entusiasmo de teletienda","Van presentando canciones inventadas por título y artista","Los actores cantan un fragmento de cada una","Cerrar con el precio y el número de teléfono"]'::jsonb, 'Canción breve, variedad de estilos, ritmo de show', '["Solo un fragmento de ocho segundos por canción","Recopilatorio de un género imposible"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 236, null),
  ('238', 'Acercar y alejar', 'juego', 12, 'grupo', 'La escena hace zoom sobre un detalle mínimo o se aleja hasta una escala enorme.', '["Empezar una escena cotidiana","Al decir ''acercar'', la escena pasa a un detalle diminuto de lo anterior","Al decir ''alejar'', se abre a un contexto mucho mayor","Cada nivel debe ser una escena de verdad, no una explicación","Volver al nivel inicial para cerrar"]'::jsonb, 'Escala, imaginación, transición', '["Hasta cinco niveles de profundidad","El público pide acercar o alejar"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 237, null),
  ('239', 'Musical: Canción de taberna', 'musical', 12, 'grupo', 'Canción colectiva de estructura fija donde cada actor aporta un verso rimado.', '["Establecer una melodía sencilla y repetitiva que todos puedan seguir","El grupo canta el estribillo a coro","Cada actor da un paso al frente y canta un verso","El verso debe rimar con el anterior","Volver al estribillo entre verso y verso"]'::jsonb, 'Rima, canto colectivo, apoyo mutuo', '["Sobre un tema propuesto por el público","Sin instrumentos, solo palmas y pies"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 238, null),
  ('240', 'Musical: Blues improvisado', 'musical', 12, 'grupo', 'Blues de doce compases donde cada actor canta sus penas sobre un tema común.', '["Establecer la base de blues con voz, palmas o instrumento","El público propone una desgracia cotidiana","Cada actor canta dos versos repetidos y uno de cierre","El resto responde con un coro sencillo","Encadenar solistas sin parar la base"]'::jsonb, 'Estructura musical fija, contenido personal, humor', '["Sobre las desgracias reales del grupo","Cambiar a otro estilo a mitad"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 239, null),
  ('241', 'Musical: Doo-wop', 'musical', 12, 'grupo', 'Un solista canta acompañado por un coro que solo hace sílabas de fondo.', '["Tres o cuatro actores forman el coro de acompañamiento","El coro establece un patrón de sílabas repetitivo","Un solista canta delante sobre el tema propuesto","El coro nunca canta letra, solo sonidos","Rotar el papel de solista sin romper el patrón"]'::jsonb, 'Acompañamiento, generosidad musical, textura coral', '["Dos solistas alternándose","El coro añade coreografía"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 240, null),
  ('242', 'Musical: Balada a dos', 'musical', 12, 'parejas', 'Dos personajes cantan una balada alternando verso a verso.', '["Establecer una melodía lenta y sencilla","Cada actor canta un verso por turno","Hay que aceptar y continuar lo que dijo el otro","Buscar un estribillo común hacia la mitad","Terminar cantando los dos a la vez"]'::jsonb, 'Escucha musical, construcción compartida, emoción', '["Los personajes están enfadados","Uno canta y el otro responde hablando"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 241, null),
  ('243', 'Musical: Cantante de hotel', 'musical', 12, 'grupo', 'Un cantante de bar de hotel improvisa canciones sobre el público que tiene delante.', '["Un actor es el cantante melódico del bar","Observa al público y elige a alguien concreto","Le dedica una canción a partir de lo que ve","Cambiar de destinatario cada canción","Mantener siempre el tono meloso y profesional"]'::jsonb, 'Observación, canción sobre la marcha, relación con el público', '["Con un pianista que sabotea","El cantante odia su trabajo"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 242, null),
  ('244', 'Musical: Himno de protesta', 'musical', 12, 'grupo', 'El grupo compone y canta un himno reivindicando algo completamente banal.', '["El público propone una causa ridícula","El grupo decide el lema y lo convierte en estribillo","Cada actor canta una estrofa con su agravio","El grupo responde con el estribillo","Terminar con una manifestación coral"]'::jsonb, 'Energía coral, compromiso, sátira', '["Con pancartas imaginarias","Contramanifestación con su propio himno"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 243, null),
  ('245', 'Musical: Salto de estilos', 'musical', 15, 'grupo', 'Una misma canción cambia de género musical cada vez que alguien lo pide.', '["Empezar a cantar una canción sobre un tema propuesto","El facilitador grita un género en cualquier momento","La canción cambia de estilo sin parar ni cambiar la letra","Pasar por al menos cinco géneros","Volver al estilo inicial para cerrar"]'::jsonb, 'Versatilidad musical, transición, memoria de letra', '["Géneros propuestos por el público","Cambio de estilo cada cuatro compases"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 244, null),
  ('246', 'Cierre: Congelado final', 'cierre', 5, 'grupo', 'El grupo construye entre todos una última imagen colectiva de la sesión.', '["Todos de pie en el espacio","Alguien entra y adopta una postura","Los demás se van sumando de uno en uno","No se puede hablar ni planificar","Mantener la imagen final diez segundos en silencio"]'::jsonb, 'Cierre visual, escucha, sensación de conjunto', '["Con un sonido colectivo al final","Fotografía de lo que fue la sesión"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 245, null),
  ('247', 'Cierre: Aplauso de dedos', 'cierre', 3, 'grupo', 'Aplauso colectivo que empieza casi inaudible y crece hasta la ovación.', '["Círculo de pie","Empezar frotando un solo dedo contra otro, casi sin sonido","Ir sumando dedos poco a poco","Pasar a palmas suaves y después a aplauso completo","Terminar con un grito colectivo"]'::jsonb, 'Cierre energético, celebración compartida', '["A la inversa, de la ovación al silencio","Dirigido por una persona"]'::jsonb, null, null, null, 'improvencyclopedia.org', true, 246, null)
on conflict (id) do nothing;

